/* MR LEE V14 – 22 chu de, 66 anh chup thuc te co nguon Wikimedia Commons */
window.MRLEE_CULTURE_V13=[{"slug":"le-hoi","title":"Lễ hội & ngày lễ","ko":"명절과 축제","icon":"🎊","group":"traditional","description":"Khám phá Seollal, Chuseok và những ngày lễ giàu ý nghĩa của Hàn Quốc.","short":"Tìm hiểu hai dịp sum họp lớn trong năm.","paragraphs":["Seollal (설날) là Tết âm lịch của người Hàn. Nhiều gia đình sum họp, ăn tteokguk và thực hiện sebae — nghi thức cúi chào chúc Tết người lớn tuổi.","Chuseok (추석) diễn ra vào ngày 15 tháng 8 âm lịch, gắn với mùa thu hoạch, thăm gia đình và những món ăn truyền thống như songpyeon. Phong tục cụ thể có thể khác nhau giữa các gia đình.","Lễ Seollal và Chuseok gắn với gia đình, nhưng không phải mọi gia đình đều tổ chức giống nhau. Người trẻ có thể cúi chào theo phép sebae, chúc sức khỏe người lớn và dùng bữa sum họp.","Trong dịp nghỉ lễ, tàu xe đường dài có thể đông; nên đặt vé và chuẩn bị lịch trình sớm. Nếu đến nhà người Hàn, hỏi trước về việc mang quà, trang phục và giờ đến."],"facts":["설날: Tết âm lịch Hàn Quốc.","추석: Lễ hội mùa thu, ngày 15 tháng 8 âm lịch.","송편: Bánh gạo thường gắn với dịp Chuseok."],"words":[{"ko":"명절","vi":"Ngày lễ truyền thống"},{"ko":"설날","vi":"Tết Seollal"},{"ko":"추석","vi":"Tết Chuseok"},{"ko":"세배","vi":"Nghi thức cúi chào năm mới"},{"ko":"송편","vi":"Bánh songpyeon"},{"ko":"가족","vi":"Gia đình"}],"dialogue":[{"ko":"설날에 무엇을 해요?","vi":"Bạn làm gì vào Tết Seollal?"},{"ko":"가족을 만나고 떡국을 먹어요.","vi":"Tôi gặp gia đình và ăn canh bánh gạo."}],"quiz":{"question":"추석은 음력 몇 월 며칠입니까?","choices":["음력 1월 1일","음력 8월 15일","양력 12월 25일"],"correct":1,"explanation":"Chuseok vào ngày 15 tháng 8 âm lịch."},"source":{"label":"VISITKOREA – Các ngày lễ truyền thống","url":"https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=1566965"},"video":null,"category":"culture","heading":"Ý nghĩa của lễ hội","tips":["Khi nhận tiền mừng tuổi hoặc quà, thường dùng hai tay để thể hiện sự trân trọng."],"steps":[{"title":"Quan sát và tìm hiểu","detail":"Xem hình minh họa, đọc hoàn cảnh sử dụng và phân biệt truyền thống với thực tế hiện nay."},{"title":"Thử tình huống thực tế","detail":"Luyện lời thoại tiếng Hàn trong bài, thay địa điểm, nhân vật và hoàn cảnh."},{"title":"Tự đối chiếu","detail":"Trả lời câu hỏi kiểm tra và dùng liên kết tham khảo để tìm hiểu sâu hơn."}],"quizSet":[{"question":"추석은 음력 몇 월 며칠입니까?","choices":["음력 1월 1일","음력 8월 15일","양력 12월 25일"],"correct":1,"explanation":"Chuseok vào ngày 15 tháng 8 âm lịch."}],"mediaLabel":"Hình minh họa chủ đề · bản quyền MR LEE","sourceLinks":[{"label":"VISITKOREA – Các ngày lễ truyền thống","url":"https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=1566965"}],"image":"images/culture-v13/le-hoi.svg","realPhotos":[{"title":"Hanbok trong ngày lễ và trải nghiệm văn hóa","explanation":"Người mặc hanbok ở cung Gyeongbokgung. Trong các dịp lễ, trang phục truyền thống thể hiện sự trân trọng nghi thức, nhưng không phải người dân Hàn nào cũng mặc hanbok hằng ngày.","filename":"One girl wearing traditional Korean costume in Gyeongbokgung,the Seoul palace 04.jpg","source":"https://commons.wikimedia.org/wiki/File:One_girl_wearing_traditional_Korean_costume_in_Gyeongbokgung,the_Seoul_palace_04.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4f/One_girl_wearing_traditional_Korean_costume_in_Gyeongbokgung,the_Seoul_palace_04.jpg/540px-One_girl_wearing_traditional_Korean_costume_in_Gyeongbokgung,the_Seoul_palace_04.jpg","local":"images/culture-v14/4f813d122c9a78a3.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Trò chơi gia đình trong dịp đầu năm","explanation":"Yutnori dùng các thanh gỗ ném và bàn cờ, thường được chơi trong những dịp sum họp. Quan sát ảnh để nhận biết dụng cụ thay vì nhầm với trò chơi điện tử hiện đại.","filename":"Yut Nori.jpg","source":"https://commons.wikimedia.org/wiki/File:Yut_Nori.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Yut_Nori.jpg/540px-Yut_Nori.jpg","local":"images/culture-v14/8b7e08cb49a46f3f.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Không gian truyền thống giữa đô thị Seoul","explanation":"Nhà hanok vẫn xuất hiện trong nhiều khu phố cổ. Dịp Seollal và Chuseok là lúc nhiều gia đình thăm nhau; việc tụ họp tùy thuộc tập quán từng nhà.","filename":"Bukchon Hanok Village Mar 2025 26.jpg","source":"https://commons.wikimedia.org/wiki/File:Bukchon_Hanok_Village_Mar_2025_26.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f7/Bukchon_Hanok_Village_Mar_2025_26.jpg/540px-Bukchon_Hanok_Village_Mar_2025_26.jpg","local":"images/culture-v14/f7315e9f3afd7391.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"am-thuc","title":"Ẩm thực Hàn Quốc","ko":"한국 음식","icon":"🥢","group":"traditional","description":"Tìm hiểu kimchi, bibimbap, banchan và văn hóa ăn uống.","short":"Món ăn chứa đựng câu chuyện cộng đồng.","paragraphs":["Ẩm thực Hàn Quốc thường kết hợp cơm, canh và các món ăn kèm (반찬). Kimchi (김치) là nhóm món rau củ lên men, có nhiều kiểu chế biến theo vùng miền và mùa.","Kimjang (김장) là tập quán làm và chia sẻ kimchi, được UNESCO ghi danh là di sản văn hóa phi vật thể vào năm 2013. Bên cạnh đó còn có bibimbap, bulgogi, tteokbokki và nhiều món đặc trưng khác.","Bữa ăn Hàn Quốc thường có cơm, canh và các món ăn kèm banchan dùng chung. Kimchi là món lên men phổ biến, nhưng khẩu vị và cách chế biến thay đổi theo gia đình và vùng miền.","Ở nhà hàng, cần chú ý món có cay, hải sản hoặc thành phần gây dị ứng; có thể hỏi nhân viên trước khi gọi. Khi ăn theo nhóm, phép lịch sự về thứ tự phục vụ và cách dùng đũa tùy hoàn cảnh."],"facts":["김치: Món rau củ lên men.","반찬: Món ăn kèm trong bữa cơm.","김장: Tập quán cùng làm và chia sẻ kimchi."],"words":[{"ko":"김치","vi":"Kimchi"},{"ko":"비빔밥","vi":"Cơm trộn"},{"ko":"반찬","vi":"Món ăn kèm"},{"ko":"발효","vi":"Lên men"},{"ko":"맛있다","vi":"Ngon"},{"ko":"주문하다","vi":"Gọi món"}],"dialogue":[{"ko":"어떤 음식을 좋아해요?","vi":"Bạn thích món ăn nào?"},{"ko":"저는 비빔밥을 좋아해요.","vi":"Tôi thích cơm trộn."}],"quiz":{"question":"김치는 주로 어떤 음식입니까?","choices":["발효 음식","과일 주스","빵 종류"],"correct":0,"explanation":"Kimchi là nhóm món lên men, thường được chế biến từ rau củ."},"source":{"label":"UNESCO – Kimjang, làm và chia sẻ kimchi","url":"https://ich.unesco.org/en/RL/kimjang-making-and-sharing-kimchi-in-the-republic-of-korea-00881"},"video":{"label":"Video UNESCO – Kimjang","url":"https://www.youtube.com/watch?v=RlBxerNfzzI"},"category":"culture","heading":"Ăn uống cùng người Hàn","tips":["Nếu ăn chay hoặc dị ứng, đừng chỉ nhìn ảnh món ăn: hãy hỏi cụ thể thành phần."],"steps":[{"title":"Quan sát và tìm hiểu","detail":"Xem hình minh họa, đọc hoàn cảnh sử dụng và phân biệt truyền thống với thực tế hiện nay."},{"title":"Thử tình huống thực tế","detail":"Luyện lời thoại tiếng Hàn trong bài, thay địa điểm, nhân vật và hoàn cảnh."},{"title":"Tự đối chiếu","detail":"Trả lời câu hỏi kiểm tra và dùng liên kết tham khảo để tìm hiểu sâu hơn."}],"quizSet":[{"question":"김치는 주로 어떤 음식입니까?","choices":["발효 음식","과일 주스","빵 종류"],"correct":0,"explanation":"Kimchi là nhóm món lên men, thường được chế biến từ rau củ."}],"mediaLabel":"Hình minh họa chủ đề · bản quyền MR LEE","sourceLinks":[{"label":"UNESCO – Kimjang, làm và chia sẻ kimchi","url":"https://ich.unesco.org/en/RL/kimjang-making-and-sharing-kimchi-in-the-republic-of-korea-00881"}],"image":"images/culture-v13/am-thuc.svg","realPhotos":[{"title":"Bàn ăn Hàn Quốc có cơm, canh và món kèm","explanation":"Một bữa ăn có thể bày bibimbap, kimchi, canh jjigae và banchan. Phân biệt món chính với món kèm, đồng thời lưu ý thức ăn cay và nguyên liệu gây dị ứng.","filename":"Korean.food-Bibimbap.Kimchi.Jjigae.Banchan.jpg","source":"https://commons.wikimedia.org/wiki/File:Korean.food-Bibimbap.Kimchi.Jjigae.Banchan.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/Korean.food-Bibimbap.Kimchi.Jjigae.Banchan.jpg/540px-Korean.food-Bibimbap.Kimchi.Jjigae.Banchan.jpg","local":"images/culture-v14/6edd4d60e9ae704b.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Các loại kimchi và banchan ở chợ","explanation":"Kimchi và banchan có nhiều kiểu chế biến theo rau củ, mùa và địa phương. Không nên hiểu kimchi chỉ có duy nhất một loại cải thảo màu đỏ.","filename":"Seoul-Kimchi and banchan.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul-Kimchi_and_banchan.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Seoul-Kimchi_and_banchan.jpg/540px-Seoul-Kimchi_and_banchan.jpg","local":"images/culture-v14/59c2bf086cf0f266.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Bánh bindaetteok được chiên tại chợ","explanation":"Ảnh ghi lại người bán chế biến bánh đậu xanh tại chợ Gwangjang. Các khu chợ truyền thống là nơi trải nghiệm đồ ăn đường phố nhưng cần chú ý giá và vệ sinh thực phẩm.","filename":"Frying Bindaetteok.jpg","source":"https://commons.wikimedia.org/wiki/File:Frying_Bindaetteok.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Frying_Bindaetteok.jpg/540px-Frying_Bindaetteok.jpg","local":"images/culture-v14/6c6b19e28d5d1bae.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"truyen-thong","title":"Trang phục & truyền thống","ko":"전통문화","icon":"👘","group":"traditional","description":"Hanbok, Hanok và những nét đẹp của sinh hoạt truyền thống.","short":"Trang phục và không gian sống kể chuyện quá khứ.","paragraphs":["Hanbok (한복) là tên gọi trang phục truyền thống của Hàn Quốc, được mặc trong một số ngày lễ và sự kiện đặc biệt. Màu sắc, chất liệu và kiểu dáng hanbok thay đổi theo thời kỳ.","Hanok (한옥) là kiểu nhà truyền thống. Một số ngôi nhà có sân trong và cấu trúc thích ứng với thời tiết. Ngày nay, du khách có thể trải nghiệm hanbok hoặc tham quan làng hanok ở nhiều địa phương.","Hanbok gồm các thành phần đặc trưng như jeogori, chima hoặc baji. Ngày nay hanbok thường xuất hiện trong lễ hội, đám cưới và các hoạt động trải nghiệm văn hóa.","Khi thuê hanbok ở khu cung điện, nên hỏi rõ thời gian trả, phụ phí và quy tắc chụp ảnh. Phân biệt trang phục truyền thống với các biến thể hiện đại trong phim ảnh."],"facts":["한복: Trang phục truyền thống.","한옥: Kiến trúc nhà truyền thống.","전통: Những giá trị hoặc phong tục được truyền lại."],"words":[{"ko":"한복","vi":"Hanbok"},{"ko":"한옥","vi":"Nhà Hanok"},{"ko":"전통","vi":"Truyền thống"},{"ko":"입다","vi":"Mặc (quần áo)"},{"ko":"마을","vi":"Ngôi làng"},{"ko":"체험하다","vi":"Trải nghiệm"}],"dialogue":[{"ko":"한복을 입어 봤어요?","vi":"Bạn từng mặc hanbok chưa?"},{"ko":"네, 여행할 때 입어 봤어요.","vi":"Rồi, tôi đã thử mặc khi đi du lịch."}],"quiz":{"question":"한옥은 무엇입니까?","choices":["전통 가옥","한국 음식","현대 교통수단"],"correct":0,"explanation":"Hanok là kiểu nhà truyền thống Hàn Quốc."},"source":null,"video":null,"category":"culture","heading":"Trang phục và di sản sống","tips":["Khi vào cung điện và nơi tôn giáo, tuân thủ biển hướng dẫn và không chạm hiện vật."],"steps":[{"title":"Quan sát và tìm hiểu","detail":"Xem hình minh họa, đọc hoàn cảnh sử dụng và phân biệt truyền thống với thực tế hiện nay."},{"title":"Thử tình huống thực tế","detail":"Luyện lời thoại tiếng Hàn trong bài, thay địa điểm, nhân vật và hoàn cảnh."},{"title":"Tự đối chiếu","detail":"Trả lời câu hỏi kiểm tra và dùng liên kết tham khảo để tìm hiểu sâu hơn."}],"quizSet":[{"question":"한옥은 무엇입니까?","choices":["전통 가옥","한국 음식","현대 교통수단"],"correct":0,"explanation":"Hanok là kiểu nhà truyền thống Hàn Quốc."}],"mediaLabel":"Hình minh họa chủ đề · bản quyền MR LEE","sourceLinks":[],"image":"images/culture-v13/truyen-thong.svg","realPhotos":[{"title":"Hanbok: cấu trúc trang phục truyền thống","explanation":"Trang phục hanbok gồm áo jeogori kết hợp chima hoặc baji. Màu sắc và kiểu dáng thay đổi theo dịp sử dụng, lứa tuổi và cách tân hiện đại.","filename":"One girl wearing traditional Korean costume in Gyeongbokgung,the Seoul palace 04.jpg","source":"https://commons.wikimedia.org/wiki/File:One_girl_wearing_traditional_Korean_costume_in_Gyeongbokgung,the_Seoul_palace_04.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4f/One_girl_wearing_traditional_Korean_costume_in_Gyeongbokgung,the_Seoul_palace_04.jpg/540px-One_girl_wearing_traditional_Korean_costume_in_Gyeongbokgung,the_Seoul_palace_04.jpg","local":"images/culture-v14/4f813d122c9a78a3.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Những mái nhà hanok tại Bukchon","explanation":"Mái cong và sân trong là nét dễ nhận biết của nhiều ngôi hanok. Đây là kiến trúc truyền thống được bảo tồn trong khu dân cư hiện đại.","filename":"Bukchon Hanok Village Mar 2025 26.jpg","source":"https://commons.wikimedia.org/wiki/File:Bukchon_Hanok_Village_Mar_2025_26.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f7/Bukchon_Hanok_Village_Mar_2025_26.jpg/540px-Bukchon_Hanok_Village_Mar_2025_26.jpg","local":"images/culture-v14/f7315e9f3afd7391.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Nhà cổ vẫn là không gian sinh hoạt thật","explanation":"Bukchon không chỉ là điểm chụp ảnh mà còn có cư dân đang sinh sống. Du khách cần giữ trật tự, tôn trọng lối vào nhà và quy định tham quan.","filename":"Bukchon Hanok Village Mar 2025 31.jpg","source":"https://commons.wikimedia.org/wiki/File:Bukchon_Hanok_Village_Mar_2025_31.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Bukchon_Hanok_Village_Mar_2025_31.jpg/540px-Bukchon_Hanok_Village_Mar_2025_31.jpg","local":"images/culture-v14/1b17948d6871ff90.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"doi-song","title":"Cuộc sống hằng ngày","ko":"한국 생활","icon":"🏙️","group":"everyday","description":"Hiểu cách sinh hoạt, đi lại, mua sắm và sử dụng tiện ích tại Hàn Quốc.","short":"Từ cửa hàng tiện lợi đến tàu điện ngầm.","paragraphs":["Tại nhiều thành phố Hàn Quốc, người dân sử dụng tàu điện ngầm, xe buýt và thẻ giao thông để đi lại. Cửa hàng tiện lợi thường bán đồ ăn nhanh, nước uống và vật dụng thiết yếu.","Một số thói quen như phân loại rác, giữ trật tự trên phương tiện công cộng và kiểm tra quy định tại nơi cư trú rất hữu ích với học sinh, du học sinh và du khách.","Nhà tiện lợi, khu dân cư, căn hộ và các dịch vụ giao hàng hiện diện rộng rãi. Tuy nhiên lịch sinh hoạt khác nhau giữa thành thị, nông thôn và từng nhóm tuổi.","Rác thải thường được phân loại theo quy định địa phương; túi rác chuyên dụng và lịch đổ rác có thể thay đổi theo quận. Hãy xem thông báo tại nơi cư trú thay vì áp dụng một quy tắc cho mọi nơi."],"facts":["편의점: Cửa hàng tiện lợi.","지하철: Tàu điện ngầm.","교통카드: Thẻ giao thông."],"words":[{"ko":"편의점","vi":"Cửa hàng tiện lợi"},{"ko":"지하철","vi":"Tàu điện ngầm"},{"ko":"버스","vi":"Xe buýt"},{"ko":"교통카드","vi":"Thẻ giao thông"},{"ko":"분리수거","vi":"Phân loại rác"},{"ko":"길","vi":"Đường đi"}],"dialogue":[{"ko":"지하철역이 어디에 있어요?","vi":"Ga tàu điện ngầm ở đâu?"},{"ko":"저쪽에 있어요.","vi":"Ở phía bên kia."}],"quiz":{"question":"편의점은 어떤 곳입니까?","choices":["책을 빌리는 곳","생활용품을 사는 곳","수업을 듣는 곳"],"correct":1,"explanation":"편의점 là cửa hàng tiện lợi, nơi mua đồ ăn, nước uống và vật dụng thường dùng."},"source":null,"video":null,"category":"culture","heading":"Nhịp sống tại Hàn Quốc","tips":["Trước khi chuyển nhà, tìm hiểu quy định đổ rác, gửi hàng và giờ yên tĩnh của tòa nhà."],"steps":[{"title":"Quan sát và tìm hiểu","detail":"Xem hình minh họa, đọc hoàn cảnh sử dụng và phân biệt truyền thống với thực tế hiện nay."},{"title":"Thử tình huống thực tế","detail":"Luyện lời thoại tiếng Hàn trong bài, thay địa điểm, nhân vật và hoàn cảnh."},{"title":"Tự đối chiếu","detail":"Trả lời câu hỏi kiểm tra và dùng liên kết tham khảo để tìm hiểu sâu hơn."}],"quizSet":[{"question":"편의점은 어떤 곳입니까?","choices":["책을 빌리는 곳","생활용품을 사는 곳","수업을 듣는 곳"],"correct":1,"explanation":"편의점 là cửa hàng tiện lợi, nơi mua đồ ăn, nước uống và vật dụng thường dùng."}],"mediaLabel":"Hình minh họa chủ đề · bản quyền MR LEE","sourceLinks":[],"image":"images/culture-v13/doi-song.svg","realPhotos":[{"title":"Hàng quán nhỏ trong đường phố Seoul","explanation":"Ảnh phản ánh hoạt động buôn bán thường ngày. Khi mua đồ ở quầy nhỏ, hãy hỏi giá và phương thức thanh toán trước khi quyết định.","filename":"Street vendor in seoul.jpg","source":"https://commons.wikimedia.org/wiki/File:Street_vendor_in_seoul.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Street_vendor_in_seoul.jpg/540px-Street_vendor_in_seoul.jpg","local":"images/culture-v14/32bb7e7ec44582c2.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Xe buýt là phương tiện phổ biến","explanation":"Các tuyến xe buýt thành phố phân chia theo màu và số tuyến. Cần kiểm tra điểm dừng và chiều di chuyển, không chỉ dựa vào màu xe.","filename":"Seoul Blue Bus.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul_Blue_Bus.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Seoul_Blue_Bus.jpg/540px-Seoul_Blue_Bus.jpg","local":"images/culture-v14/eb63e9656be01d60.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Nhà ga tàu điện trong đời sống đô thị","explanation":"Người dân sử dụng nhiều loại phương tiện công cộng; biển tên ga, số tuyến và hướng đi là ba yếu tố quan trọng khi định vị.","filename":"Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg/540px-Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg","local":"images/culture-v14/2864ad555a023c67.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"phe-lich-su","title":"Phép lịch sự & ứng xử","ko":"한국 예절","icon":"🙇","group":"everyday","description":"Lời chào, kính ngữ, cách xưng hô và sự tôn trọng trong giao tiếp.","short":"Giao tiếp phù hợp với hoàn cảnh và mối quan hệ.","paragraphs":["Tiếng Hàn có nhiều mức độ lịch sự. Khi mới gặp người lớn tuổi, giáo viên hoặc người chưa thân, người học thường sử dụng đuôi câu lịch sự như -요 hoặc -습니다.","Cúi chào nhẹ, nói lời cảm ơn và chú ý cách gọi người đối diện có thể giúp giao tiếp tự nhiên hơn. Quy tắc ứng xử thực tế còn tùy mối quan hệ, bối cảnh và từng người.","Tiếng Hàn có cách nói lịch sự và kính ngữ. Cách gọi người lớn tuổi, cấp trên hoặc người mới gặp thường khác cách nói với bạn thân.","Tại nơi trang trọng, trao nhận danh thiếp hoặc vật dụng bằng hai tay có thể thể hiện sự tôn trọng. Tuy vậy, phép lịch sự tùy quan hệ và bối cảnh; đừng máy móc coi mọi cử chỉ là quy tắc bắt buộc."],"facts":["존댓말: Cách nói lịch sự/kính ngữ.","인사: Lời chào.","감사합니다: Xin cảm ơn (lịch sự)."],"words":[{"ko":"예절","vi":"Lễ nghi, phép lịch sự"},{"ko":"존댓말","vi":"Lối nói lịch sự"},{"ko":"인사하다","vi":"Chào hỏi"},{"ko":"감사합니다","vi":"Xin cảm ơn"},{"ko":"죄송합니다","vi":"Tôi xin lỗi"},{"ko":"어른","vi":"Người lớn tuổi"}],"dialogue":[{"ko":"안녕하세요?","vi":"Xin chào ạ."},{"ko":"안녕하세요. 만나서 반갑습니다.","vi":"Xin chào. Rất vui được gặp bạn."}],"quiz":{"question":"처음 만난 사람에게 보통 어떤 표현을 씁니까?","choices":["야, 뭐 해?","안녕하세요?","잘 자!"],"correct":1,"explanation":"안녕하세요? là lời chào lịch sự phù hợp trong nhiều tình huống gặp mặt."},"source":null,"video":null,"category":"culture","heading":"Tôn trọng trong lời nói và cử chỉ","tips":["Chưa chắc nên xưng hô thế nào? Dùng đuôi lịch sự -요 và hỏi cách gọi phù hợp."],"steps":[{"title":"Quan sát và tìm hiểu","detail":"Xem hình minh họa, đọc hoàn cảnh sử dụng và phân biệt truyền thống với thực tế hiện nay."},{"title":"Thử tình huống thực tế","detail":"Luyện lời thoại tiếng Hàn trong bài, thay địa điểm, nhân vật và hoàn cảnh."},{"title":"Tự đối chiếu","detail":"Trả lời câu hỏi kiểm tra và dùng liên kết tham khảo để tìm hiểu sâu hơn."}],"quizSet":[{"question":"처음 만난 사람에게 보통 어떤 표현을 씁니까?","choices":["야, 뭐 해?","안녕하세요?","잘 자!"],"correct":1,"explanation":"안녕하세요? là lời chào lịch sự phù hợp trong nhiều tình huống gặp mặt."}],"mediaLabel":"Hình minh họa chủ đề · bản quyền MR LEE","sourceLinks":[],"image":"images/culture-v13/phe-lich-su.svg","realPhotos":[{"title":"Trang phục trang trọng trong không gian di sản","explanation":"Phong cách ăn mặc và hành vi lịch sự thay đổi theo bối cảnh. Ở nơi trang nghiêm, cách ứng xử thường chuẩn mực hơn sinh hoạt thường ngày.","filename":"One girl wearing traditional Korean costume in Gyeongbokgung,the Seoul palace 04.jpg","source":"https://commons.wikimedia.org/wiki/File:One_girl_wearing_traditional_Korean_costume_in_Gyeongbokgung,the_Seoul_palace_04.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4f/One_girl_wearing_traditional_Korean_costume_in_Gyeongbokgung,the_Seoul_palace_04.jpg/540px-One_girl_wearing_traditional_Korean_costume_in_Gyeongbokgung,the_Seoul_palace_04.jpg","local":"images/culture-v14/4f813d122c9a78a3.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Tôn trọng không gian sống và cộng đồng","explanation":"Đường phố Bukchon có cư dân, không phải mọi lối đi đều là khu tham quan. Nói vừa phải, không bước vào sân nhà và tôn trọng biển cấm chụp ảnh.","filename":"Bukchon Hanok Village Mar 2025 25.jpg","source":"https://commons.wikimedia.org/wiki/File:Bukchon_Hanok_Village_Mar_2025_25.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Bukchon_Hanok_Village_Mar_2025_25.jpg/540px-Bukchon_Hanok_Village_Mar_2025_25.jpg","local":"images/culture-v14/42baaf5c54f18ab2.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Phép lịch sự trong bữa ăn","explanation":"Bữa ăn thường đặt nhiều món kèm ở giữa bàn. Lời mời ăn, dùng đũa/muỗng và thứ tự phục vụ có thể thay đổi theo gia đình, nhóm tuổi và bối cảnh.","filename":"Korean.food-Bibimbap.Kimchi.Jjigae.Banchan.jpg","source":"https://commons.wikimedia.org/wiki/File:Korean.food-Bibimbap.Kimchi.Jjigae.Banchan.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/Korean.food-Bibimbap.Kimchi.Jjigae.Banchan.jpg/540px-Korean.food-Bibimbap.Kimchi.Jjigae.Banchan.jpg","local":"images/culture-v14/6edd4d60e9ae704b.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"giao-duc","title":"Giáo dục & du học","ko":"교육과 유학","icon":"🎓","group":"everyday","description":"Trường học, ký túc xá, đại học và trải nghiệm của du học sinh.","short":"Chuẩn bị từ vựng cho môi trường học tập.","paragraphs":["Năm học ở nhiều cơ sở giáo dục Hàn Quốc bắt đầu vào tháng 3. Các trường đại học thường chia năm học thành hai học kỳ chính; lịch cụ thể tùy trường.","Du học sinh nên tìm hiểu quy định đăng ký môn học, ký túc xá, bảo hiểm và thủ tục cư trú qua trang chính thức của trường và cơ quan liên quan.","Hệ thống giáo dục Hàn Quốc có trường phổ thông, cao đẳng, đại học và các viện đào tạo tiếng Hàn. Điều kiện tuyển sinh, thời gian nhập học và chứng chỉ ngoại ngữ tùy trường.","Khi nộp hồ sơ, nên kiểm tra nguồn chính thức của trường, học phí, ký túc xá, bảo hiểm và quy định visa. TOPIK có thể là một trong nhiều điều kiện, không thay thế mọi yêu cầu tuyển sinh."],"facts":["학기: Học kỳ.","기숙사: Ký túc xá.","수강 신청: Đăng ký môn học."],"words":[{"ko":"대학교","vi":"Đại học"},{"ko":"학생","vi":"Học sinh, sinh viên"},{"ko":"학기","vi":"Học kỳ"},{"ko":"기숙사","vi":"Ký túc xá"},{"ko":"수업","vi":"Tiết học"},{"ko":"장학금","vi":"Học bổng"}],"dialogue":[{"ko":"기숙사에서 살아요?","vi":"Bạn sống trong ký túc xá à?"},{"ko":"네, 학교 기숙사에서 살아요.","vi":"Vâng, tôi sống ở ký túc xá của trường."}],"quiz":{"question":"기숙사는 무엇입니까?","choices":["학교 숙소","식당 메뉴","시험 문제"],"correct":0,"explanation":"기숙사 là ký túc xá, nơi ở dành cho người học."},"source":null,"video":null,"category":"culture","heading":"Học tập và du học","tips":["Lưu các hạn nộp, bản dịch giấy tờ và email xác nhận; không chỉ dựa vào lời quảng cáo."],"steps":[{"title":"Quan sát và tìm hiểu","detail":"Xem hình minh họa, đọc hoàn cảnh sử dụng và phân biệt truyền thống với thực tế hiện nay."},{"title":"Thử tình huống thực tế","detail":"Luyện lời thoại tiếng Hàn trong bài, thay địa điểm, nhân vật và hoàn cảnh."},{"title":"Tự đối chiếu","detail":"Trả lời câu hỏi kiểm tra và dùng liên kết tham khảo để tìm hiểu sâu hơn."}],"quizSet":[{"question":"기숙사는 무엇입니까?","choices":["학교 숙소","식당 메뉴","시험 문제"],"correct":0,"explanation":"기숙사 là ký túc xá, nơi ở dành cho người học."}],"mediaLabel":"Hình minh họa chủ đề · bản quyền MR LEE","sourceLinks":[],"image":"images/culture-v13/giao-duc.svg","realPhotos":[{"title":"Trường học tại Seoul","explanation":"Một trường tiểu học ở Seoul. Chương trình học và nội quy phụ thuộc cấp học; học viên du học cần tìm hiểu cụ thể trường mình đăng ký.","filename":"Seoul Daelim Elementary School.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul_Daelim_Elementary_School.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Seoul_Daelim_Elementary_School.jpg/540px-Seoul_Daelim_Elementary_School.jpg","local":"images/culture-v14/ddca4db03813776e.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Khuôn viên trường đại học","explanation":"Không gian đại học tại Seoul gồm giảng đường và khu nghiên cứu. Du học sinh cần lưu ý các quy định về đăng ký tín chỉ, học phí và nghỉ học.","filename":"Campus of Seoul National University of Technology. Seoultech. Snut..jpg","source":"https://commons.wikimedia.org/wiki/File:Campus_of_Seoul_National_University_of_Technology._Seoultech._Snut..jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Campus_of_Seoul_National_University_of_Technology._Seoultech._Snut..jpg/540px-Campus_of_Seoul_National_University_of_Technology._Seoultech._Snut..jpg","local":"images/culture-v14/b1c88dfdb10650b1.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Môi trường học tập trong đô thị","explanation":"Ảnh cho thấy cơ sở trường học khác tại Seoul. Việc tìm hiểu đường đến trường và phương tiện công cộng giúp giảm bỡ ngỡ những ngày đầu.","filename":"Korea-seoul-gaewoong-elementary-school.jpg","source":"https://commons.wikimedia.org/wiki/File:Korea-seoul-gaewoong-elementary-school.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/Korea-seoul-gaewoong-elementary-school.jpg/540px-Korea-seoul-gaewoong-elementary-school.jpg","local":"images/culture-v14/1c0d0f59600f8b14.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"du-lich","title":"Du lịch & địa danh","ko":"한국 여행","icon":"🗺️","group":"everyday","description":"Khám phá Seoul, Busan, Jeju và những địa danh văn hóa đặc sắc.","short":"Mỗi vùng có cảnh quan và phong cách riêng.","paragraphs":["Seoul là thủ đô Hàn Quốc, nổi bật với sự kết hợp giữa cung điện, bảo tàng và không gian đô thị hiện đại. Busan nằm ở phía đông nam bán đảo Triều Tiên, được biết đến với cảnh biển và các khu chợ.","Jeju là đảo nổi tiếng với cảnh quan thiên nhiên. Khi du lịch, bạn có thể luyện các mẫu câu hỏi đường, mua vé, đặt phòng và hỏi giờ mở cửa.","Hàn Quốc có cung điện và khu phố cổ ở Seoul, bờ biển Busan, di sản Gyeongju, đảo Jeju và nhiều vùng miền với bản sắc riêng.","Điểm đến đông khách cần lưu ý giờ hoạt động, quy định đặt vé, thời tiết và tuyến giao thông. Khi đi vùng núi hoặc biển, kiểm tra cảnh báo thời tiết và không vào khu vực bị hạn chế."],"facts":["서울: Seoul.","부산: Busan.","제주도: Đảo Jeju."],"words":[{"ko":"여행","vi":"Du lịch"},{"ko":"서울","vi":"Seoul"},{"ko":"부산","vi":"Busan"},{"ko":"제주도","vi":"Đảo Jeju"},{"ko":"관광지","vi":"Điểm du lịch"},{"ko":"표","vi":"Vé"}],"dialogue":[{"ko":"서울에 가 봤어요?","vi":"Bạn đã từng đến Seoul chưa?"},{"ko":"아니요, 다음에 가 보고 싶어요.","vi":"Chưa, lần tới tôi muốn thử đến đó."}],"quiz":{"question":"제주도는 어떤 곳입니까?","choices":["섬","지하철역","음식 이름"],"correct":0,"explanation":"제주도 là đảo Jeju, một địa danh thiên nhiên nổi tiếng."},"source":null,"video":null,"category":"culture","heading":"Khám phá các vùng miền","tips":["Nên lưu địa chỉ địa điểm bằng tiếng Hàn để dễ hỏi đường."],"steps":[{"title":"Quan sát và tìm hiểu","detail":"Xem hình minh họa, đọc hoàn cảnh sử dụng và phân biệt truyền thống với thực tế hiện nay."},{"title":"Thử tình huống thực tế","detail":"Luyện lời thoại tiếng Hàn trong bài, thay địa điểm, nhân vật và hoàn cảnh."},{"title":"Tự đối chiếu","detail":"Trả lời câu hỏi kiểm tra và dùng liên kết tham khảo để tìm hiểu sâu hơn."}],"quizSet":[{"question":"제주도는 어떤 곳입니까?","choices":["섬","지하철역","음식 이름"],"correct":0,"explanation":"제주도 là đảo Jeju, một địa danh thiên nhiên nổi tiếng."}],"mediaLabel":"Hình minh họa chủ đề · bản quyền MR LEE","sourceLinks":[],"image":"images/culture-v13/du-lich.svg","realPhotos":[{"title":"Làng hanok Bukchon","explanation":"Bukchon là một khu cư trú có nhà truyền thống. Đi tham quan nên kiểm tra giờ giới hạn và tuân thủ biển hướng dẫn.","filename":"Bukchon Hanok Village Mar 2025 31.jpg","source":"https://commons.wikimedia.org/wiki/File:Bukchon_Hanok_Village_Mar_2025_31.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Bukchon_Hanok_Village_Mar_2025_31.jpg/540px-Bukchon_Hanok_Village_Mar_2025_31.jpg","local":"images/culture-v14/1b17948d6871ff90.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Tháp Namsan và đường chân trời Seoul","explanation":"N Seoul Tower là địa điểm quen thuộc để ngắm cảnh thành phố. Nên kiểm tra thời tiết, cách lên núi và phương tiện công cộng trước chuyến đi.","filename":"Namsan Tower.jpg","source":"https://commons.wikimedia.org/wiki/File:Namsan_Tower.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Namsan_Tower.jpg/540px-Namsan_Tower.jpg","local":"images/culture-v14/4e9ee4f5450f8618.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Trải nghiệm hanbok tại cung điện","explanation":"Khách có thể thuê hanbok chụp ảnh ở khu cung điện. Trước khi thuê, hỏi phụ phí, thời gian trả và các khu vực hạn chế.","filename":"One girl wearing traditional Korean costume in Gyeongbokgung,the Seoul palace 04.jpg","source":"https://commons.wikimedia.org/wiki/File:One_girl_wearing_traditional_Korean_costume_in_Gyeongbokgung,the_Seoul_palace_04.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4f/One_girl_wearing_traditional_Korean_costume_in_Gyeongbokgung,the_Seoul_palace_04.jpg/540px-One_girl_wearing_traditional_Korean_costume_in_Gyeongbokgung,the_Seoul_palace_04.jpg","local":"images/culture-v14/4f813d122c9a78a3.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"kpop","title":"K-pop & giải trí","ko":"대중문화","icon":"🎤","group":"modern","description":"Âm nhạc, phim truyền hình, chương trình giải trí và cộng đồng người hâm mộ.","short":"Học tiếng Hàn qua nội dung giải trí yêu thích.","paragraphs":["K-pop là cách gọi phổ biến cho dòng nhạc đại chúng Hàn Quốc, gắn với nhiều hình thức biểu diễn và hoạt động của người hâm mộ. Phim truyền hình Hàn Quốc (드라마) và chương trình giải trí cũng được đón xem ở nhiều quốc gia.","Khi học qua phim và bài hát, hãy chú ý phân biệt ngôn ngữ thân mật với lời nói lịch sự; không phải câu thoại nào cũng phù hợp để sử dụng trong đời thực.","K-pop là một phần của ngành giải trí Hàn Quốc, bên cạnh phim truyền hình, điện ảnh, sân khấu, nhạc truyền thống và các chương trình tạp kỹ.","Văn hóa người hâm mộ có những quy định riêng về vé, bản quyền, quyền riêng tư của nghệ sĩ và ứng xử tại sự kiện. Hãy mua vé qua kênh chính thức và không phát tán thông tin cá nhân."],"facts":["대중문화: Văn hóa đại chúng.","가수: Ca sĩ.","드라마: Phim truyền hình."],"words":[{"ko":"가수","vi":"Ca sĩ"},{"ko":"노래","vi":"Bài hát"},{"ko":"드라마","vi":"Phim truyền hình"},{"ko":"팬","vi":"Người hâm mộ"},{"ko":"공연","vi":"Biểu diễn"},{"ko":"자막","vi":"Phụ đề"}],"dialogue":[{"ko":"어떤 노래를 좋아해요?","vi":"Bạn thích bài hát nào?"},{"ko":"저는 한국 노래를 자주 들어요.","vi":"Tôi thường nghe nhạc Hàn Quốc."}],"quiz":{"question":"드라마는 무엇입니까?","choices":["드라마 시리즈","전통 음식","교통카드"],"correct":0,"explanation":"드라마 thường chỉ phim truyền hình hoặc chuỗi phim nhiều tập."},"source":null,"video":null,"category":"culture","heading":"Âm nhạc và đời sống giải trí","tips":["Không phải mọi người Hàn Quốc đều thích K-pop; hãy tránh quy chụp sở thích."],"steps":[{"title":"Quan sát và tìm hiểu","detail":"Xem hình minh họa, đọc hoàn cảnh sử dụng và phân biệt truyền thống với thực tế hiện nay."},{"title":"Thử tình huống thực tế","detail":"Luyện lời thoại tiếng Hàn trong bài, thay địa điểm, nhân vật và hoàn cảnh."},{"title":"Tự đối chiếu","detail":"Trả lời câu hỏi kiểm tra và dùng liên kết tham khảo để tìm hiểu sâu hơn."}],"quizSet":[{"question":"드라마는 무엇입니까?","choices":["드라마 시리즈","전통 음식","교통카드"],"correct":0,"explanation":"드라마 thường chỉ phim truyền hình hoặc chuỗi phim nhiều tập."}],"mediaLabel":"Hình minh họa chủ đề · bản quyền MR LEE","sourceLinks":[],"image":"images/culture-v13/kpop.svg","realPhotos":[{"title":"Sân khấu biểu diễn K-pop","explanation":"Ảnh sân khấu biểu diễn tại Incheon. K-pop bao gồm biểu diễn trực tiếp, vũ đạo, đội ngũ âm thanh và hoạt động người hâm mộ.","filename":"160924 Incheon Kpop Concert.jpg","source":"https://commons.wikimedia.org/wiki/File:160924_Incheon_Kpop_Concert.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/160924_Incheon_Kpop_Concert.jpg/540px-160924_Incheon_Kpop_Concert.jpg","local":"images/culture-v14/2b648f5bb096a15c.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Vũ đạo đồng bộ trên sân khấu","explanation":"Nhóm nhạc thể hiện các động tác theo nhịp, ánh sáng và nhạc nền. Khán giả cần tuân thủ quy định quay phim, xếp hàng và vé của sự kiện.","filename":"Close Your Eyes Kpop live concert stage performance 2026 1.jpg","source":"https://commons.wikimedia.org/wiki/File:Close_Your_Eyes_Kpop_live_concert_stage_performance_2026_1.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Close_Your_Eyes_Kpop_live_concert_stage_performance_2026_1.jpg/540px-Close_Your_Eyes_Kpop_live_concert_stage_performance_2026_1.jpg","local":"images/culture-v14/5beb8d69bce5b98e.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"K-pop được yêu thích và thực hành ở nhiều nơi","explanation":"Ảnh một buổi biểu diễn vũ đạo theo phong cách K-pop ở ngoài Hàn Quốc. Hiện tượng này cho thấy ảnh hưởng văn hóa vượt ra khỏi biên giới.","filename":"Dance movement of KPOP Korean Pop.jpg","source":"https://commons.wikimedia.org/wiki/File:Dance_movement_of_KPOP_Korean_Pop.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Dance_movement_of_KPOP_Korean_Pop.jpg/540px-Dance_movement_of_KPOP_Korean_Pop.jpg","local":"images/culture-v14/674b8e25140c0d62.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"cong-so","title":"Văn hóa công sở","ko":"직장 문화","icon":"💼","group":"modern","description":"Giao tiếp trong doanh nghiệp, giờ làm việc và cách ứng xử chuyên nghiệp.","short":"Biết cách trao đổi nơi làm việc.","paragraphs":["Tại nơi làm việc, việc chào đồng nghiệp, giao tiếp rõ ràng và dùng cách nói phù hợp là những kỹ năng quan trọng. Một số doanh nghiệp có hoạt động ăn tối tập thể gọi là 회식.","Văn hóa công sở có sự khác biệt lớn giữa công ty, thế hệ và ngành nghề. Khi mới đi làm, nên tìm hiểu quy trình và quy định riêng của nơi làm việc thay vì giả định mọi công ty giống nhau.","Một số nơi làm việc có hệ thống chức danh và quy trình báo cáo khá rõ. Tuy vậy, văn hóa công sở thay đổi đáng kể giữa startup, cơ quan, nhà máy và tập đoàn.","Giao tiếp đúng thời hạn, xác nhận yêu cầu bằng văn bản, tôn trọng lịch họp và xin phép khi cần hỗ trợ giúp giảm hiểu lầm. Người lao động cần hiểu hợp đồng và quy định làm việc của mình."],"facts":["출근하다: Đi làm.","퇴근하다: Tan làm.","회의: Cuộc họp."],"words":[{"ko":"회사","vi":"Công ty"},{"ko":"직원","vi":"Nhân viên"},{"ko":"출근하다","vi":"Đi làm"},{"ko":"퇴근하다","vi":"Tan làm"},{"ko":"회의","vi":"Cuộc họp"},{"ko":"동료","vi":"Đồng nghiệp"}],"dialogue":[{"ko":"회의가 몇 시에 시작해요?","vi":"Cuộc họp bắt đầu lúc mấy giờ?"},{"ko":"오전 열 시에 시작해요.","vi":"Bắt đầu lúc 10 giờ sáng."}],"quiz":{"question":"퇴근하다는 무슨 뜻입니까?","choices":["일을 시작하다","일을 마치고 나가다","식사하다"],"correct":1,"explanation":"퇴근하다 nghĩa là tan làm, rời chỗ làm sau giờ làm việc."},"source":null,"video":null,"category":"culture","heading":"Môi trường làm việc Hàn Quốc","tips":["Nếu hướng dẫn chưa rõ, hỏi lại bằng câu lịch sự thay vì đoán ý."],"steps":[{"title":"Quan sát và tìm hiểu","detail":"Xem hình minh họa, đọc hoàn cảnh sử dụng và phân biệt truyền thống với thực tế hiện nay."},{"title":"Thử tình huống thực tế","detail":"Luyện lời thoại tiếng Hàn trong bài, thay địa điểm, nhân vật và hoàn cảnh."},{"title":"Tự đối chiếu","detail":"Trả lời câu hỏi kiểm tra và dùng liên kết tham khảo để tìm hiểu sâu hơn."}],"quizSet":[{"question":"퇴근하다는 무슨 뜻입니까?","choices":["일을 시작하다","일을 마치고 나가다","식사하다"],"correct":1,"explanation":"퇴근하다 nghĩa là tan làm, rời chỗ làm sau giờ làm việc."}],"mediaLabel":"Hình minh họa chủ đề · bản quyền MR LEE","sourceLinks":[],"image":"images/culture-v13/cong-so.svg","realPhotos":[{"title":"Môi trường làm việc, đào tạo kỹ năng","explanation":"Không gian cơ sở giáo dục cũng là nơi diễn ra nghiên cứu và công việc. Trong môi trường chuyên nghiệp cần chú ý lịch hẹn, thư điện tử và ngôn ngữ kính ngữ.","filename":"Campus of Seoul National University of Technology. Seoultech. Snut..jpg","source":"https://commons.wikimedia.org/wiki/File:Campus_of_Seoul_National_University_of_Technology._Seoultech._Snut..jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Campus_of_Seoul_National_University_of_Technology._Seoultech._Snut..jpg/540px-Campus_of_Seoul_National_University_of_Technology._Seoultech._Snut..jpg","local":"images/culture-v14/b1c88dfdb10650b1.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Nếp sinh hoạt và dịch vụ ngoài văn phòng","explanation":"Nhân viên văn phòng sử dụng dịch vụ đô thị xung quanh nơi làm việc. Khi đặt lịch, ăn trưa hoặc gặp đối tác, sự đúng giờ thường rất quan trọng.","filename":"Seoul market street.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul_market_street.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/Seoul_market_street.jpg/540px-Seoul_market_street.jpg","local":"images/culture-v14/f9a6edf435cf70ae.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Công việc trong thành phố lớn","explanation":"Seoul tập trung nhiều doanh nghiệp và các dịch vụ. Văn hóa công sở không hoàn toàn giống nhau giữa công ty khởi nghiệp và tổ chức truyền thống.","filename":"Namsan Tower.jpg","source":"https://commons.wikimedia.org/wiki/File:Namsan_Tower.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Namsan_Tower.jpg/540px-Namsan_Tower.jpg","local":"images/culture-v14/4e9ee4f5450f8618.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"tro-choi","title":"Trò chơi & thể thao","ko":"놀이와 스포츠","icon":"🥋","group":"traditional","description":"Yutnori, Jegichagi, Taekwondo và các hoạt động cộng đồng.","short":"Vừa chơi vừa học từ vựng.","paragraphs":["Yutnori (윷놀이) là trò chơi dân gian sử dụng các thanh gỗ để quyết định bước đi trên bàn chơi. Jegichagi (제기차기) là trò đá cầu truyền thống, thường gắn với các hoạt động vui chơi ngày lễ.","Taekwondo (태권도) là môn võ xuất phát từ Hàn Quốc, nổi bật với kỹ thuật đá và hệ thống cấp đai. Trò chơi và thể thao giúp người học hiểu thêm về sinh hoạt văn hóa.","Các trò như yutnori, jegichagi hay tuho thường xuất hiện trong sự kiện văn hóa và các dịp lễ. Thể thao hiện đại, đặc biệt bóng đá và bóng chày, cũng được quan tâm rộng rãi.","Khi tham gia trò chơi truyền thống, hãy tìm hiểu luật đơn giản trước rồi thử cùng nhóm. Với môn thể thao ngoài trời, luôn chú ý thời tiết, nước uống và khu vực được phép."],"facts":["윷놀이: Trò chơi gậy yut.","제기차기: Đá cầu truyền thống.","태권도: Võ Taekwondo."],"words":[{"ko":"놀이","vi":"Trò chơi"},{"ko":"윷놀이","vi":"Yutnori"},{"ko":"제기차기","vi":"Jegichagi"},{"ko":"태권도","vi":"Taekwondo"},{"ko":"운동","vi":"Vận động, thể thao"},{"ko":"친구","vi":"Bạn bè"}],"dialogue":[{"ko":"무슨 운동을 좋아해요?","vi":"Bạn thích môn thể thao nào?"},{"ko":"저는 태권도를 좋아해요.","vi":"Tôi thích Taekwondo."}],"quiz":{"question":"윷놀이는 무엇입니까?","choices":["전통 놀이","대학교 이름","한국 음식"],"correct":0,"explanation":"윷놀이 là trò chơi dân gian truyền thống."},"source":null,"video":null,"category":"culture","heading":"Vui chơi và vận động","tips":["Cùng chơi là dịp thực hành các câu cổ vũ và hướng dẫn bằng tiếng Hàn."],"steps":[{"title":"Quan sát và tìm hiểu","detail":"Xem hình minh họa, đọc hoàn cảnh sử dụng và phân biệt truyền thống với thực tế hiện nay."},{"title":"Thử tình huống thực tế","detail":"Luyện lời thoại tiếng Hàn trong bài, thay địa điểm, nhân vật và hoàn cảnh."},{"title":"Tự đối chiếu","detail":"Trả lời câu hỏi kiểm tra và dùng liên kết tham khảo để tìm hiểu sâu hơn."}],"quizSet":[{"question":"윷놀이는 무엇입니까?","choices":["전통 놀이","대학교 이름","한국 음식"],"correct":0,"explanation":"윷놀이 là trò chơi dân gian truyền thống."}],"mediaLabel":"Hình minh họa chủ đề · bản quyền MR LEE","sourceLinks":[],"image":"images/culture-v13/tro-choi.svg","realPhotos":[{"title":"Bàn cờ Yutnori","explanation":"Trò chơi truyền thống có bàn cờ và các thanh ném. Học viên có thể quan sát cách phân biệt dụng cụ trò chơi với các môn thể thao.","filename":"Yut Nori.jpg","source":"https://commons.wikimedia.org/wiki/File:Yut_Nori.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Yut_Nori.jpg/540px-Yut_Nori.jpg","local":"images/culture-v14/8b7e08cb49a46f3f.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Hoạt động trò chơi truyền thống","explanation":"Trò chơi dân gian thường được tổ chức trong ngày lễ hoặc sự kiện cộng đồng. Cách chơi và luật cụ thể cần được hướng dẫn trước khi tham gia.","filename":"Korean Traditional Game 20170128.jpg","source":"https://commons.wikimedia.org/wiki/File:Korean_Traditional_Game_20170128.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Korean_Traditional_Game_20170128.jpg/540px-Korean_Traditional_Game_20170128.jpg","local":"images/culture-v14/0cfc636dab9c6f61.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Giải trí và sự kiện tập thể hiện đại","explanation":"Không chỉ có trò chơi dân gian, đời sống giải trí hiện nay còn có hòa nhạc và các hoạt động cộng đồng lớn.","filename":"160924 Incheon Kpop Concert.jpg","source":"https://commons.wikimedia.org/wiki/File:160924_Incheon_Kpop_Concert.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/160924_Incheon_Kpop_Concert.jpg/540px-160924_Incheon_Kpop_Concert.jpg","local":"images/culture-v14/2b648f5bb096a15c.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"lich-su","title":"Lịch sử & di sản","ko":"역사와 유산","icon":"🏯","group":"traditional","description":"Hangeul, vua Sejong, cung điện và các dấu ấn lịch sử Hàn Quốc.","short":"Hiểu nguồn gốc chữ viết và các di sản.","paragraphs":["Hangeul (한글) là hệ chữ viết tiếng Hàn. Dưới thời vua Sejong, bộ chữ được sáng tạo vào thế kỷ XV và công bố dưới tên Hunminjeongeum (훈민정음) vào năm 1446.","Những cung điện như Gyeongbokgung (경복궁) tại Seoul phản ánh một phần lịch sử triều đại Joseon. Khi tham quan di tích, hãy chú ý tìm hiểu bối cảnh thời kỳ thay vì nhìn nhận lịch sử như một câu chuyện duy nhất.","Hàn Quốc có nhiều thời kỳ lịch sử với thành tựu kiến trúc, chữ viết, học thuật và nghệ thuật khác nhau. Cung điện, làng truyền thống và bảo tàng giúp hình dung đời sống từng thời.","Khi tham quan di tích, nên đọc chú giải để phân biệt công trình nguyên gốc, phục dựng và trưng bày mô phỏng. Tránh đánh đồng di sản lịch sử với cảnh dựng trong phim."],"facts":["한글: Chữ Hangeul.","세종대왕: Vua Sejong.","경복궁: Cung Gyeongbokgung."],"words":[{"ko":"역사","vi":"Lịch sử"},{"ko":"한글","vi":"Chữ Hangeul"},{"ko":"세종대왕","vi":"Vua Sejong"},{"ko":"궁궐","vi":"Cung điện"},{"ko":"유산","vi":"Di sản"},{"ko":"박물관","vi":"Bảo tàng"}],"dialogue":[{"ko":"한글을 누가 만들었어요?","vi":"Ai đã tạo ra chữ Hangeul?"},{"ko":"세종대왕 때 만들었어요.","vi":"Chữ được tạo ra dưới thời vua Sejong."}],"quiz":{"question":"한글은 무엇입니까?","choices":["한국의 문자","한국 음식","전통 운동"],"correct":0,"explanation":"한글 là hệ chữ viết của tiếng Hàn."},"source":null,"video":null,"category":"culture","heading":"Nhìn văn hóa qua chiều dài lịch sử","tips":["Một địa danh có thể mang nhiều lớp ký ức; nên tham khảo bảo tàng hoặc nguồn chính thống."],"steps":[{"title":"Quan sát và tìm hiểu","detail":"Xem hình minh họa, đọc hoàn cảnh sử dụng và phân biệt truyền thống với thực tế hiện nay."},{"title":"Thử tình huống thực tế","detail":"Luyện lời thoại tiếng Hàn trong bài, thay địa điểm, nhân vật và hoàn cảnh."},{"title":"Tự đối chiếu","detail":"Trả lời câu hỏi kiểm tra và dùng liên kết tham khảo để tìm hiểu sâu hơn."}],"quizSet":[{"question":"한글은 무엇입니까?","choices":["한국의 문자","한국 음식","전통 운동"],"correct":0,"explanation":"한글 là hệ chữ viết của tiếng Hàn."}],"mediaLabel":"Hình minh họa chủ đề · bản quyền MR LEE","sourceLinks":[],"image":"images/culture-v13/lich-su.svg","realPhotos":[{"title":"Đời sống chợ Hàn Quốc trong tư liệu cũ","explanation":"Ảnh tư liệu khoảng năm 1951 cho thấy người bán hàng ngoài phố. Đây là lát cắt lịch sử, không đại diện cho hình ảnh Hàn Quốc hiện nay.","filename":"Korean Street Markets.jpg","source":"https://commons.wikimedia.org/wiki/File:Korean_Street_Markets.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/9/9d/Korean_Street_Markets.jpg","local":"images/culture-v14/9d415ff06d4deee5.jpg","licenseNote":"Ảnh lịch sử: Gene Putnam / Harry S. Truman Library & Museum; phạm vi công cộng tại Mỹ (PD US Government)."},{"title":"Cảnh họp chợ giữa thế kỷ XX","explanation":"Ảnh tư liệu giai đoạn sau chiến tranh ghi lại hoạt động mua bán trong điều kiện khó khăn; so sánh với Seoul ngày nay để thấy sự thay đổi.","filename":"South Korean Street Market.jpg","source":"https://commons.wikimedia.org/wiki/File:South_Korean_Street_Market.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/South_Korean_Street_Market.jpg/540px-South_Korean_Street_Market.jpg","local":"images/culture-v14/90bbdf207fb4cd35.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Di sản được bảo tồn đến hiện tại","explanation":"Nhà truyền thống trong đô thị hiện đại nhắc lại lịch sử kiến trúc, nhưng nhiều công trình đã trải qua phục dựng hoặc bảo trì.","filename":"Bukchon Hanok Village Mar 2025 26.jpg","source":"https://commons.wikimedia.org/wiki/File:Bukchon_Hanok_Village_Mar_2025_26.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f7/Bukchon_Hanok_Village_Mar_2025_26.jpg/540px-Bukchon_Hanok_Village_Mar_2025_26.jpg","local":"images/culture-v14/f7315e9f3afd7391.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"hien-dai","title":"Hàn Quốc hiện đại","ko":"현대 한국","icon":"✨","group":"modern","description":"Cà phê, công nghệ, xu hướng mới và nhịp sống đô thị.","short":"Khám phá Hàn Quốc ngày nay.","paragraphs":["Ở các đô thị lớn của Hàn Quốc, quán cà phê, dịch vụ giao đồ ăn và thanh toán điện tử là những phần quen thuộc của đời sống nhiều người. Những trải nghiệm này cũng giúp học viên luyện từ vựng thực tế.","Hàn Quốc hiện đại có nhiều sắc thái giữa thành thị và nông thôn, thế hệ và địa phương. Tìm hiểu các khác biệt này giúp tránh suy nghĩ rằng mọi người đều sống theo một khuôn mẫu.","Hệ thống thanh toán, vận tải, công nghệ tiêu dùng và dịch vụ trực tuyến phát triển mạnh tại nhiều thành phố. Song không phải mọi dịch vụ đều hỗ trợ ngoại ngữ hoặc thẻ quốc tế.","Khi dùng ứng dụng địa phương, chú ý quyền riêng tư, bảo mật tài khoản và kết nối Internet. Nên chuẩn bị phương án dự phòng nếu điện thoại hết pin hoặc thẻ thanh toán không hoạt động."],"facts":["카페: Quán cà phê.","배달: Giao hàng.","현대: Hiện đại."],"words":[{"ko":"현대","vi":"Hiện đại"},{"ko":"카페","vi":"Quán cà phê"},{"ko":"배달","vi":"Giao hàng"},{"ko":"기술","vi":"Công nghệ"},{"ko":"결제하다","vi":"Thanh toán"},{"ko":"편리하다","vi":"Tiện lợi"}],"dialogue":[{"ko":"커피를 배달시킬까요?","vi":"Chúng ta đặt giao cà phê nhé?"},{"ko":"좋아요. 앱으로 주문해요.","vi":"Được đó. Hãy đặt qua ứng dụng."}],"quiz":{"question":"배달은 무슨 뜻입니까?","choices":["배달 서비스","지하철역","수업 시간"],"correct":0,"explanation":"배달 là giao hàng, giao đồ ăn hoặc giao vật phẩm tới địa điểm nhận."},"source":null,"video":null,"category":"culture","heading":"Hàn Quốc trong thời đại số","tips":["Lưu số điện thoại liên lạc khẩn cấp và địa chỉ chỗ ở ở dạng ngoại tuyến."],"steps":[{"title":"Quan sát và tìm hiểu","detail":"Xem hình minh họa, đọc hoàn cảnh sử dụng và phân biệt truyền thống với thực tế hiện nay."},{"title":"Thử tình huống thực tế","detail":"Luyện lời thoại tiếng Hàn trong bài, thay địa điểm, nhân vật và hoàn cảnh."},{"title":"Tự đối chiếu","detail":"Trả lời câu hỏi kiểm tra và dùng liên kết tham khảo để tìm hiểu sâu hơn."}],"quizSet":[{"question":"배달은 무슨 뜻입니까?","choices":["배달 서비스","지하철역","수업 시간"],"correct":0,"explanation":"배달 là giao hàng, giao đồ ăn hoặc giao vật phẩm tới địa điểm nhận."}],"mediaLabel":"Hình minh họa chủ đề · bản quyền MR LEE","sourceLinks":[],"image":"images/culture-v13/hien-dai.svg","realPhotos":[{"title":"Seoul hiện đại nhìn từ xa","explanation":"Những khu dân cư và đường giao thông hiện đại cho thấy tốc độ đô thị hóa. Hàn Quốc đồng thời duy trì nhiều không gian văn hóa cổ.","filename":"Namsan Tower.jpg","source":"https://commons.wikimedia.org/wiki/File:Namsan_Tower.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Namsan_Tower.jpg/540px-Namsan_Tower.jpg","local":"images/culture-v14/4e9ee4f5450f8618.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Giao thông công cộng hiện đại","explanation":"Hệ thống buýt và tàu điện hỗ trợ di chuyển hằng ngày. Người mới đến cần học đọc số tuyến, điểm trung chuyển và quy tắc an toàn.","filename":"Seoul Blue Bus.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul_Blue_Bus.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Seoul_Blue_Bus.jpg/540px-Seoul_Blue_Bus.jpg","local":"images/culture-v14/eb63e9656be01d60.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Hạ tầng nhà ga đô thị","explanation":"Biển ga kết hợp chữ Hàn, số ga và chỉ dẫn. Đây là kỹ năng thực tế cần thiết khi du học và làm việc tại Hàn Quốc.","filename":"Seoul-metro-531-Chungjeongno-station-platform-20180915-132214.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul-metro-531-Chungjeongno-station-platform-20180915-132214.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ec/Seoul-metro-531-Chungjeongno-station-platform-20180915-132214.jpg/540px-Seoul-metro-531-Chungjeongno-station-platform-20180915-132214.jpg","local":"images/culture-v14/ecd6e11e8e24a1fb.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"so-cap-cuu","title":"Sơ cấp cứu & CPR","ko":"응급처치·심폐소생술","icon":"🫀","group":"life","category":"life","description":"Khi gặp người bất tỉnh hoặc không thở bình thường","heading":"Kỹ năng sống: Sơ cấp cứu & CPR","short":"Khi gặp người bất tỉnh hoặc không thở bình thường","paragraphs":["Đầu tiên hãy bảo đảm khu vực an toàn: tránh giao thông, điện, khói hoặc vật rơi. Kiểm tra người gặp nạn có đáp ứng và thở bình thường hay không.","Ở Hàn Quốc, gọi 119 để yêu cầu xe cứu thương. Nếu người lớn bất tỉnh và không thở bình thường, nhờ người khác gọi 119, lấy AED; bắt đầu ép tim theo hướng dẫn tổng đài.","Ép tim người lớn bằng gót bàn tay ở giữa ngực trên nền phẳng, tốc độ khoảng 100–120 lần/phút, để ngực nở lại giữa các lần ép. Nếu có AED, bật thiết bị và làm đúng theo hướng dẫn.","Đây là nội dung định hướng nhận biết và hành động ban đầu, không thay thế khóa huấn luyện CPR/sơ cấp cứu chính quy. Trẻ em, trẻ sơ sinh và trường hợp chấn thương cần cách xử trí riêng."],"facts":[],"tips":["Nếu có nguy hiểm trực tiếp tới tính mạng hoặc sức khỏe, gọi 119 hoặc 112 phù hợp với tình huống; 1330 chỉ hỗ trợ thông tin/phiên dịch du lịch."],"steps":[{"title":"Đảm bảo an toàn","detail":"Kiểm tra nguy hiểm trước khi tiếp cận; không tự đưa mình vào nơi có điện giật, cháy hoặc xe đang chạy."},{"title":"Kiểm tra tình trạng","detail":"Gọi to, vỗ nhẹ vai và quan sát hơi thở bình thường."},{"title":"Gọi 119","detail":"Nói rõ địa điểm, tình trạng nạn nhân; bật loa ngoài để làm theo hướng dẫn."},{"title":"Hồi sức & AED","detail":"Nếu đủ điều kiện theo chỉ dẫn, ép tim người lớn và dùng AED theo lời nhắc của thiết bị."},{"title":"Bàn giao","detail":"Tiếp tục theo hướng dẫn 119 đến khi nhân viên chuyên môn tiếp nhận."}],"words":[{"ko":"응급처치","vi":"Sơ cấp cứu"},{"ko":"심폐소생술","vi":"CPR/hồi sức tim phổi"},{"ko":"의식이 없어요","vi":"Bất tỉnh"},{"ko":"숨을 안 쉬어요","vi":"Không thở"},{"ko":"구급차","vi":"Xe cứu thương"},{"ko":"자동심장충격기","vi":"AED"}],"dialogue":[{"ko":"사람이 쓰러졌어요. 119에 신고해 주세요.","vi":"Có người ngã bất tỉnh. Hãy gọi 119."},{"ko":"위치는 서울역 2번 출구 앞입니다.","vi":"Địa điểm là trước lối ra số 2 ga Seoul."}],"quizSet":[{"question":"Người lớn bất tỉnh, không thở bình thường. Việc cần làm trước tiên là gì?","choices":["Chờ vài phút rồi xem","Đảm bảo an toàn, gọi 119 và làm theo hướng dẫn","Cho uống nước"],"correct":1,"explanation":"Hãy dựa trên các bước xử lý an toàn đã hướng dẫn trong bài."}],"sourceLinks":[{"label":"Hướng dẫn sơ cấp cứu CPR – Red Cross","url":"https://www.redcross.org/take-a-class/cpr/performing-cpr/hands-only-cpr"},{"label":"Dịch vụ khẩn cấp tại Hàn Quốc – VISITKOREA","url":"https://english.visitkorea.or.kr/svc/contents/infoHtmlView.do?vcontsId=140042"}],"mediaLabel":"Hình minh họa kỹ năng thực tế · bản quyền MR LEE","image":"images/culture-v13/so-cap-cuu.svg","realPhotos":[{"title":"Huấn luyện CPR trên mô hình","explanation":"Ảnh nhân viên Không quân Hoa Kỳ thực hành hồi sức tim phổi trên mô hình huấn luyện. Đây không phải hiện trường ở Hàn Quốc. Khi có người bất tỉnh, gọi 119 và làm theo hướng dẫn của điều phối viên; việc thực hành CPR nên được đào tạo chuyên môn.","filename":"CPR Dummy-Air Force.JPG","source":"https://commons.wikimedia.org/wiki/File:CPR_Dummy-Air_Force.JPG","remote":"https://upload.wikimedia.org/wikipedia/commons/2/2c/CPR_Dummy-Air_Force.JPG","local":"images/culture-v14/e2d0f1c957a157f5.jpg","licenseNote":"Ảnh: Maj. Ted Theopolos / U.S. Air Force; phạm vi công cộng tại Mỹ (tác phẩm chính phủ Hoa Kỳ)."},{"title":"Thực hành ép tim với hình nhân","explanation":"Lớp huấn luyện sử dụng hình nhân nhằm tránh gây nguy hiểm cho người thật. Chỉ hình ảnh không đủ để học kỹ thuật; hãy tham gia khóa sơ cấp cứu có chứng nhận.","filename":"119th Medical Group CPR training DVIDS356471.jpg","source":"https://commons.wikimedia.org/wiki/File:119th_Medical_Group_CPR_training_DVIDS356471.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/16/119th_Medical_Group_CPR_training_DVIDS356471.jpg/540px-119th_Medical_Group_CPR_training_DVIDS356471.jpg","local":"images/culture-v14/16dc9c1c04dd8f5a.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Tập sử dụng thiết bị AED","explanation":"Học viên được giới thiệu AED trong buổi huấn luyện. Khi cần dùng thiết bị thật, tuân thủ chỉ dẫn bằng giọng của máy và tổng đài cứu hộ.","filename":"US Navy 120117-N-KK576-025 A Sailor instructs a class on how to properly operate an automated external defibrillator.jpg","source":"https://commons.wikimedia.org/wiki/File:US_Navy_120117-N-KK576-025_A_Sailor_instructs_a_class_on_how_to_properly_operate_an_automated_external_defibrillator.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/US_Navy_120117-N-KK576-025_A_Sailor_instructs_a_class_on_how_to_properly_operate_an_automated_external_defibrillator.jpg/540px-US_Navy_120117-N-KK576-025_A_Sailor_instructs_a_class_on_how_to_properly_operate_an_automated_external_defibrillator.jpg","local":"images/culture-v14/62a2daf2139f3626.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"goi-cuu-ho","title":"Gọi cứu hộ & số khẩn cấp","ko":"긴급 신고·구조 요청","icon":"🚑","group":"life","category":"life","description":"Phân biệt 119 – 112 – 1330 và cách trình bày tình huống","heading":"Kỹ năng sống: Gọi cứu hộ & số khẩn cấp","short":"Phân biệt 119 – 112 – 1330 và cách trình bày tình huống","paragraphs":["119 kết nối cứu hỏa, cứu nạn và cấp cứu y tế; 112 là cảnh sát. 1330 là tổng đài hỗ trợ du lịch, thông tin và phiên dịch, không phải số thay thế 112/119 trong tình huống nguy hiểm.","Khi gọi, cố gắng nói địa chỉ, mốc gần nhất hoặc số lối ra ga tàu, loại sự cố, số người bị ảnh hưởng và số điện thoại liên lạc.","Nếu không nói được tiếng Hàn, có thể đề nghị phiên dịch, nói chậm và gửi vị trí GPS nếu tổng đài hướng dẫn. Trong khẩn cấp thật, ưu tiên gọi đúng số ngay.","Ví dụ: nếu bạn ở ga tàu, hãy đọc cả tên ga và số lối ra. Nếu gọi từ phòng ở, nêu tên tòa nhà, tầng và số phòng để nhân viên dễ tìm."],"facts":[],"tips":["Nếu có nguy hiểm trực tiếp tới tính mạng hoặc sức khỏe, gọi 119 hoặc 112 phù hợp với tình huống; 1330 chỉ hỗ trợ thông tin/phiên dịch du lịch."],"steps":[{"title":"Chọn số đúng","detail":"119 nếu có cháy, tai nạn y tế, cứu nạn; 112 nếu có bạo lực, trộm cắp hay đe dọa."},{"title":"Xác định vị trí","detail":"Đọc tên đường, tòa nhà, tầng, cửa ra ga hoặc gửi ghim vị trí khi được yêu cầu."},{"title":"Nói vấn đề chính","detail":"Ai bị làm sao, có bao nhiêu người, còn nguy hiểm không."},{"title":"Làm theo tổng đài","detail":"Giữ liên lạc và làm theo chỉ dẫn an toàn phù hợp."}],"words":[{"ko":"긴급 신고","vi":"Báo khẩn cấp"},{"ko":"경찰","vi":"Cảnh sát"},{"ko":"소방서","vi":"Cứu hỏa"},{"ko":"구급차","vi":"Xe cấp cứu"},{"ko":"위치","vi":"Vị trí"},{"ko":"통역","vi":"Phiên dịch"}],"dialogue":[{"ko":"도와주세요! 사람이 다쳤어요.","vi":"Xin giúp với! Có người bị thương."},{"ko":"제 위치는 지하철역 3번 출구입니다.","vi":"Tôi ở lối ra số 3 ga tàu điện ngầm."}],"quizSet":[{"question":"Trường hợp cháy nhà và có người bị thương ở Hàn Quốc, gọi số nào?","choices":["119","1330","114"],"correct":0,"explanation":"Hãy dựa trên các bước xử lý an toàn đã hướng dẫn trong bài."}],"sourceLinks":[{"label":"Số hỗ trợ du lịch và khẩn cấp – VISITKOREA","url":"https://english.visitkorea.or.kr/svc/contents/infoHtmlView.do?vcontsId=140042"}],"mediaLabel":"Hình minh họa kỹ năng thực tế · bản quyền MR LEE","image":"images/culture-v13/goi-cuu-ho.svg","realPhotos":[{"title":"Xe cứu hỏa tại Seoul — liên hệ 119","explanation":"Hình xe cứu hỏa thực tế tại Seoul. Khi báo hỏa hoạn, cần ưu tiên nói rõ địa chỉ, tầng và khu vực có khói hoặc người mắc kẹt.","filename":"20170622 Hyundai Mighty fire engine of Seoul-side.jpg","source":"https://commons.wikimedia.org/wiki/File:20170622_Hyundai_Mighty_fire_engine_of_Seoul-side.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/20170622_Hyundai_Mighty_fire_engine_of_Seoul-side.jpg/540px-20170622_Hyundai_Mighty_fire_engine_of_Seoul-side.jpg","local":"images/culture-v14/23df912d2f90e751.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Xe cảnh sát — liên hệ 112","explanation":"Ảnh xe cảnh sát ở Seoul. Gọi 112 khi có đe dọa an ninh hoặc hành vi phạm pháp; không dùng số khẩn cấp cho thắc mắc du lịch thông thường.","filename":"Police car in Seoul, South Korea.jpg","source":"https://commons.wikimedia.org/wiki/File:Police_car_in_Seoul,_South_Korea.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Police_car_in_Seoul,_South_Korea.jpg/540px-Police_car_in_Seoul,_South_Korea.jpg","local":"images/culture-v14/2ed3e5e0921f0d46.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Xác định vị trí khi gọi trợ giúp","explanation":"Biển tên ga và số hiệu có thể giúp mô tả vị trí. Hãy đọc chính xác tên ga, lối ra và mốc gần đó cho tổng đài.","filename":"Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg/540px-Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg","local":"images/culture-v14/2864ad555a023c67.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"lac-duong","title":"Khi lạc đường","ko":"길을 잃었을 때","icon":"🗺️","group":"life","category":"life","description":"Tìm đường, hỏi lối ra ga và tìm điểm hẹn an toàn","heading":"Kỹ năng sống: Khi lạc đường","short":"Tìm đường, hỏi lối ra ga và tìm điểm hẹn an toàn","paragraphs":["Đứng ở nơi sáng, dễ nhận biết và không cản trở dòng người. Mở bản đồ, tìm tên ga, số lối ra và địa chỉ bằng chữ Hàn.","Nếu không có mạng, hỏi nhân viên ga, quầy thông tin hoặc cửa hàng có người trực. Tránh đi theo người lạ đến khu vực vắng vẻ chỉ vì họ đề nghị giúp.","1330 có thể hỗ trợ thông tin du lịch hoặc phiên dịch. Nếu đang bị đe dọa, gọi 112 thay vì coi đó là tình huống hỏi đường thông thường.","Hãy chụp trước địa chỉ nơi ở và lưu ngoại tuyến tên bằng chữ Hàn; đây là giải pháp dự phòng khi mạng di động yếu hoặc điện thoại gần hết pin."],"facts":[],"tips":["Nếu có nguy hiểm trực tiếp tới tính mạng hoặc sức khỏe, gọi 119 hoặc 112 phù hợp với tình huống; 1330 chỉ hỗ trợ thông tin/phiên dịch du lịch."],"steps":[{"title":"Dừng ở nơi an toàn","detail":"Không vừa đi vừa dò bản đồ giữa đường xe."},{"title":"Xác định mốc","detail":"Ghi tên ga, số cửa ra, tên đường hoặc địa điểm lớn."},{"title":"Hỏi người có trách nhiệm","detail":"Ưu tiên quầy thông tin, nhân viên ga hoặc cảnh sát."},{"title":"Liên hệ người quen","detail":"Gửi vị trí và hẹn tại điểm công cộng."}],"words":[{"ko":"길을 잃었어요","vi":"Tôi bị lạc"},{"ko":"어디예요?","vi":"Ở đâu?"},{"ko":"출구","vi":"Lối ra"},{"ko":"역무원","vi":"Nhân viên ga"},{"ko":"지도","vi":"Bản đồ"},{"ko":"도와주세요","vi":"Xin giúp"}],"dialogue":[{"ko":"서울역 1번 출구가 어디예요?","vi":"Lối ra số 1 ga Seoul ở đâu?"},{"ko":"이쪽으로 곧장 가세요.","vi":"Đi thẳng theo hướng này."}],"quizSet":[{"question":"Khi lạc tại ga tàu, nên hỏi ai trước?","choices":["Người lạ hẹn gặp nơi vắng","Nhân viên ga/quầy thông tin","Đi đại lên tàu bất kỳ"],"correct":1,"explanation":"Hãy dựa trên các bước xử lý an toàn đã hướng dẫn trong bài."}],"sourceLinks":[{"label":"Hỗ trợ du khách – VISITKOREA","url":"https://english.visitkorea.or.kr/svc/contents/infoHtmlView.do?vcontsId=140632"}],"mediaLabel":"Hình minh họa kỹ năng thực tế · bản quyền MR LEE","image":"images/culture-v13/lac-duong.svg","realPhotos":[{"title":"Biển số cửa ra ga — điểm định vị","explanation":"Khi lạc đường trong Seoul, tên ga và số cửa ra (Exit) là mốc rất hữu ích để người khác tìm bạn hoặc chỉ đường.","filename":"Seoul Subway Line 2 and 6 Sindang Station Exit 8.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul_Subway_Line_2_and_6_Sindang_Station_Exit_8.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Seoul_Subway_Line_2_and_6_Sindang_Station_Exit_8.jpg/540px-Seoul_Subway_Line_2_and_6_Sindang_Station_Exit_8.jpg","local":"images/culture-v14/00e218c25ca2df68.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Đọc biển ga và hướng chuyển tuyến","explanation":"Ga Chungjeongno có bảng ghi số ga và mũi tên. Không chỉ nhìn tên ga, cần xác định đúng tuyến và chiều tàu.","filename":"Seoul-metro-531-Chungjeongno-station-platform-20180915-132214.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul-metro-531-Chungjeongno-station-platform-20180915-132214.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ec/Seoul-metro-531-Chungjeongno-station-platform-20180915-132214.jpg/540px-Seoul-metro-531-Chungjeongno-station-platform-20180915-132214.jpg","local":"images/culture-v14/ecd6e11e8e24a1fb.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Tìm xe công cộng khi chưa biết đường","explanation":"Nếu phải tiếp tục bằng xe buýt, hãy hỏi đúng số tuyến, điểm xuống và kiểm tra bản đồ di chuyển trên điện thoại.","filename":"Seoul Blue Bus.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul_Blue_Bus.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Seoul_Blue_Bus.jpg/540px-Seoul_Blue_Bus.jpg","local":"images/culture-v14/eb63e9656be01d60.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"mat-vi","title":"Mất ví, hộ chiếu hoặc thẻ","ko":"지갑·여권 분실","icon":"👛","group":"life","category":"life","description":"Khóa thẻ, tìm đồ thất lạc và bảo vệ giấy tờ","heading":"Kỹ năng sống: Mất ví, hộ chiếu hoặc thẻ","short":"Khóa thẻ, tìm đồ thất lạc và bảo vệ giấy tờ","paragraphs":["Khi phát hiện mất ví, kiểm tra lại tuyến đường và liên hệ địa điểm vừa đến. Nếu có thẻ thanh toán trong ví, khóa thẻ hoặc thông báo ngân hàng sớm.","Tại Hàn Quốc có cổng LOST112 của cảnh sát để tìm tài sản được nhặt và khai báo thất lạc. Nếu nghi bị trộm hoặc có nguy cơ an toàn, liên hệ cảnh sát qua 112.","Với hộ chiếu, liên hệ cơ quan đại diện ngoại giao của nước mình và cơ quan liên quan để được hướng dẫn về giấy tờ thay thế; yêu cầu có thể khác nhau theo quốc tịch.","Với thẻ cư trú hoặc giấy tờ nhận dạng khác, hãy hỏi cơ quan có thẩm quyền về thủ tục cấp lại; không đưa ảnh giấy tờ chứa dữ liệu cá nhân lên nhóm cộng đồng công khai."],"facts":[],"tips":["Nếu có nguy hiểm trực tiếp tới tính mạng hoặc sức khỏe, gọi 119 hoặc 112 phù hợp với tình huống; 1330 chỉ hỗ trợ thông tin/phiên dịch du lịch."],"steps":[{"title":"Khóa thẻ","detail":"Dùng ứng dụng hoặc tổng đài ngân hàng để hạn chế giao dịch trái phép."},{"title":"Kiểm tra điểm đã đến","detail":"Hỏi quầy thất lạc của ga/taxi/cửa hàng gần nhất."},{"title":"Tra cứu LOST112","detail":"Tìm tài sản nhặt được và khai báo khi phù hợp."},{"title":"Báo cơ quan liên quan","detail":"Với trộm cắp/hộ chiếu, liên hệ cảnh sát và đại sứ quán/lãnh sự quán."}],"words":[{"ko":"지갑","vi":"Ví"},{"ko":"여권","vi":"Hộ chiếu"},{"ko":"분실물","vi":"Đồ thất lạc"},{"ko":"신용카드","vi":"Thẻ tín dụng"},{"ko":"분실 신고","vi":"Khai báo mất"},{"ko":"찾다","vi":"Tìm thấy"}],"dialogue":[{"ko":"지갑을 잃어버렸어요.","vi":"Tôi bị mất ví."},{"ko":"분실물 센터가 어디예요?","vi":"Trung tâm đồ thất lạc ở đâu?"}],"quizSet":[{"question":"Khi mất ví có thẻ ngân hàng, thao tác nên ưu tiên là gì?","choices":["Khóa thẻ và liên hệ ngân hàng","Đăng số thẻ lên mạng","Chờ không làm gì"],"correct":0,"explanation":"Hãy dựa trên các bước xử lý an toàn đã hướng dẫn trong bài."}],"sourceLinks":[{"label":"Cổng LOST112 chính thức","url":"https://lost112.go.kr/"},{"label":"Quy trình khai báo LOST112","url":"https://lost112.go.kr/html.do?html=%2Fprevent%2FlostDeclare&sub=F&title=%EC%9C%A0%EC%8B%A4%EB%AC%BC+%EC%A2%85%ED%95%A9%EC%95%88%EB%82%B4"}],"mediaLabel":"Hình minh họa kỹ năng thực tế · bản quyền MR LEE","image":"images/culture-v13/mat-vi.svg","realPhotos":[{"title":"Khi nghi bị trộm: tìm trợ giúp cảnh sát","explanation":"Xe cảnh sát ở Seoul là hình ảnh minh họa cơ quan chức năng, không phải ảnh vụ mất ví. Khi nghi có hành vi trộm cắp, gọi 112.","filename":"Police car in Seoul, South Korea.jpg","source":"https://commons.wikimedia.org/wiki/File:Police_car_in_Seoul,_South_Korea.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Police_car_in_Seoul,_South_Korea.jpg/540px-Police_car_in_Seoul,_South_Korea.jpg","local":"images/culture-v14/2ed3e5e0921f0d46.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Liên hệ nhân viên ở điểm vừa đi qua","explanation":"Nếu rơi ví trên tàu, thông báo số tuyến, ga, thời gian và đặc điểm vật bị mất. Không tự đi vào khu vực hạn chế trong nhà ga.","filename":"Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg/540px-Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg","local":"images/culture-v14/2864ad555a023c67.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Kiểm tra các nơi đã ghé thăm","explanation":"Hãy lập danh sách cửa hàng, quầy hàng hoặc điểm dừng đã tới. Đồng thời khóa thẻ ngân hàng để giảm nguy cơ giao dịch trái phép.","filename":"Street vendor in seoul.jpg","source":"https://commons.wikimedia.org/wiki/File:Street_vendor_in_seoul.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Street_vendor_in_seoul.jpg/540px-Street_vendor_in_seoul.jpg","local":"images/culture-v14/32bb7e7ec44582c2.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"tau-dien-ngam","title":"Đi tàu điện ngầm","ko":"지하철 이용법","icon":"🚇","group":"life","category":"life","description":"Mua thẻ, tìm tuyến, đổi tàu và xuống đúng ga","heading":"Kỹ năng sống: Đi tàu điện ngầm","short":"Mua thẻ, tìm tuyến, đổi tàu và xuống đúng ga","paragraphs":["Hệ thống ga ở Seoul có biển chỉ dẫn màu tuyến, tên ga và lối ra bằng nhiều ngôn ngữ. Xem đúng hướng tàu dựa trên ga tiếp theo, không chỉ dựa trên số tuyến.","Có thể sử dụng thẻ giao thông nạp tiền (như T-money) hoặc vé đi một lượt ở máy bán vé. Chạm thẻ tại cổng vào và cổng ra; loại vé một lượt có thể có khoản đặt cọc hoàn lại theo quy định.","Đổi tuyến theo biển Transfer/환승; ghi lại tên ga trung chuyển, sân ga, chiều đi và lối ra cuối. Nếu đi nhầm hướng, hãy hỏi nhân viên để xử lý đúng thay vì tự vượt cổng.","Ở một số ga lớn có nhiều sân ga hoặc tuyến cùng màu; theo dõi cả tên ga và ký hiệu chiều đi trên bảng điện tử, hỏi nhân viên nếu đường chuyển tuyến không rõ."],"facts":[],"tips":["Nếu có nguy hiểm trực tiếp tới tính mạng hoặc sức khỏe, gọi 119 hoặc 112 phù hợp với tình huống; 1330 chỉ hỗ trợ thông tin/phiên dịch du lịch."],"steps":[{"title":"Chuẩn bị trước","detail":"Tra điểm đến, tên ga bằng tiếng Hàn và số cửa ra; nạp đủ tiền."},{"title":"Qua cổng","detail":"Chạm thẻ lên đầu đọc và kiểm tra thông báo chấp nhận."},{"title":"Lên đúng chiều","detail":"Đọc ga tiếp theo trên biển điện tử và trên đoàn tàu."},{"title":"Đổi tuyến","detail":"Đi theo ký hiệu 환승 và màu tuyến; kiểm tra lại chiều đi."},{"title":"Ra ga","detail":"Chạm thẻ ra cổng, chọn đúng số cửa ra; lấy lại đặt cọc vé một lượt khi áp dụng."}],"words":[{"ko":"지하철","vi":"Tàu điện ngầm"},{"ko":"환승","vi":"Chuyển tuyến"},{"ko":"출구","vi":"Lối ra"},{"ko":"승강장","vi":"Sân ga"},{"ko":"교통카드","vi":"Thẻ giao thông"},{"ko":"방면","vi":"Hướng đi"}],"dialogue":[{"ko":"2호선으로 갈아타려면 어디로 가야 해요?","vi":"Muốn đổi sang tuyến số 2 thì đi đâu?"},{"ko":"환승 표지판을 따라가세요.","vi":"Hãy đi theo biển chuyển tuyến."}],"quizSet":[{"question":"Trước khi lên tàu, điều nào quan trọng nhất?","choices":["Màu áo của hành khách","Hướng đi và ga tiếp theo","Số lượng quán ăn trong ga"],"correct":1,"explanation":"Hãy dựa trên các bước xử lý an toàn đã hướng dẫn trong bài."}],"sourceLinks":[{"label":"Hướng dẫn tàu điện – Visit Seoul","url":"https://english.visitseoul.net/essential-Info-article/Subway/ENN016755"},{"label":"Video hướng dẫn sân bay – tàu điện KTO","url":"https://english1.visitkorea.or.kr/enu/TRP/TP_ENG_8_6.jsp"}],"mediaLabel":"Hình minh họa kỹ năng thực tế · bản quyền MR LEE","image":"images/culture-v13/tau-dien-ngam.svg","realPhotos":[{"title":"Nền ga tàu điện Seoul — đọc tên ga","explanation":"Trên bảng ga có ký hiệu và số ga. Hãy đối chiếu với ứng dụng bản đồ để xác nhận đúng hướng và ga xuống.","filename":"Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg/540px-Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg","local":"images/culture-v14/2864ad555a023c67.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Biển chỉ dẫn chuyển tuyến","explanation":"Nhìn số ga, tên ga và hướng mũi tên. Khi đổi tuyến, đi theo đúng chỉ dẫn và không đi ngược dòng người.","filename":"Seoul-metro-531-Chungjeongno-station-platform-20180915-132214.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul-metro-531-Chungjeongno-station-platform-20180915-132214.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ec/Seoul-metro-531-Chungjeongno-station-platform-20180915-132214.jpg/540px-Seoul-metro-531-Chungjeongno-station-platform-20180915-132214.jpg","local":"images/culture-v14/ecd6e11e8e24a1fb.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Biển cửa ra ga Sindang","explanation":"Số cửa ra giúp tìm địa điểm trên mặt đất. Chọn cửa ra phù hợp trước khi rời khu vực soát vé để tránh đi vòng.","filename":"Seoul Subway Line 2 and 6 Sindang Station Exit 8.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul_Subway_Line_2_and_6_Sindang_Station_Exit_8.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Seoul_Subway_Line_2_and_6_Sindang_Station_Exit_8.jpg/540px-Seoul_Subway_Line_2_and_6_Sindang_Station_Exit_8.jpg","local":"images/culture-v14/00e218c25ca2df68.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"xe-buyt","title":"Đi xe buýt và chuyển tuyến","ko":"버스 타는 법","icon":"🚌","group":"life","category":"life","description":"Chọn đúng tuyến, quẹt thẻ và xin xuống xe","heading":"Kỹ năng sống: Đi xe buýt và chuyển tuyến","short":"Chọn đúng tuyến, quẹt thẻ và xin xuống xe","paragraphs":["Xe buýt Hàn Quốc có thể phân tuyến theo màu, số xe và địa bàn; cách vận hành phụ thuộc thành phố. Luôn đọc số tuyến và hướng xe trước khi lên.","Với thẻ giao thông, thường cần chạm thẻ lúc lên và khi xuống để áp dụng tính cước/chuyển tuyến; hãy tuân theo biển tại xe địa phương.","Nhìn màn hình thông báo điểm dừng, nhấn nút xuống trước khi tới điểm cần dừng. Khi không chắc, có thể hỏi tài xế bằng câu ngắn, lịch sự.","Đường xe buýt, giờ hoạt động và vị trí trạm có thể thay đổi do công trình hoặc thời tiết; hãy xác minh thông tin mới nhất bằng ứng dụng giao thông hoặc biển tại trạm."],"facts":[],"tips":["Nếu có nguy hiểm trực tiếp tới tính mạng hoặc sức khỏe, gọi 119 hoặc 112 phù hợp với tình huống; 1330 chỉ hỗ trợ thông tin/phiên dịch du lịch."],"steps":[{"title":"Tìm tuyến","detail":"Đối chiếu số xe, điểm đầu/cuối và chiều đi."},{"title":"Lên xe","detail":"Đợi xe dừng hẳn, nhường người xuống, chạm thẻ."},{"title":"Theo dõi điểm dừng","detail":"Xem màn hình/tên điểm dừng và chuẩn bị trước."},{"title":"Xuống xe","detail":"Nhấn chuông, xuống an toàn và chạm thẻ theo quy định."}],"words":[{"ko":"버스","vi":"Xe buýt"},{"ko":"정류장","vi":"Trạm xe"},{"ko":"하차","vi":"Xuống xe"},{"ko":"교통카드","vi":"Thẻ giao thông"},{"ko":"다음 정류장","vi":"Trạm kế tiếp"},{"ko":"벨","vi":"Chuông"}],"dialogue":[{"ko":"이 버스가 시청에 가요?","vi":"Xe này có đi đến Tòa thị chính không?"},{"ko":"네, 세 정거장 뒤에 내려요.","vi":"Có, xuống sau ba trạm."}],"quizSet":[{"question":"Khi chuẩn bị xuống xe buýt, nên làm gì?","choices":["Nhấn chuông sớm và chuẩn bị an toàn","Đứng đột ngột khi xe chạy nhanh","Mở cửa bằng tay"],"correct":0,"explanation":"Hãy dựa trên các bước xử lý an toàn đã hướng dẫn trong bài."}],"sourceLinks":[{"label":"Hướng dẫn giao thông Seoul","url":"https://english.seoul.go.kr/service/movement/public-transportation/2-subway/"}],"mediaLabel":"Hình minh họa kỹ năng thực tế · bản quyền MR LEE","image":"images/culture-v13/xe-buyt.svg","realPhotos":[{"title":"Xe buýt màu xanh tại Seoul","explanation":"Màu và số tuyến hỗ trợ nhận biết loại tuyến. Nên tra điểm dừng, thời gian dự kiến và hướng xe trước khi lên.","filename":"Seoul Blue Bus.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul_Blue_Bus.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Seoul_Blue_Bus.jpg/540px-Seoul_Blue_Bus.jpg","local":"images/culture-v14/eb63e9656be01d60.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Máy chạm thẻ giao thông T-money","explanation":"Ảnh thiết bị đọc thẻ trên xe buýt tại Sejong. Khi sử dụng thực tế, quan sát biểu tượng chạm thẻ và quy tắc lên/xuống của từng nơi.","filename":"Sejong Bus T-money.JPG","source":"https://commons.wikimedia.org/wiki/File:Sejong_Bus_T-money.JPG","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/Sejong_Bus_T-money.JPG/540px-Sejong_Bus_T-money.JPG","local":"images/culture-v14/abeb1e35e2eff0ff.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Điểm dừng xe buýt tại Seoul","explanation":"Tìm đúng điểm dừng và đọc bảng tên tuyến. Khi xe đến, xếp hàng và tránh bước xuống lòng đường trước khi xe dừng hẳn.","filename":"Seoul bus stop.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul_bus_stop.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/a/a7/Seoul_bus_stop.jpg","local":"images/culture-v14/a7cbe5f594887efb.jpg","licenseNote":"Ảnh: Trainholic; CC BY-SA 3.0 (https://creativecommons.org/licenses/by-sa/3.0/). Không chỉnh sửa ảnh."}]},{"slug":"benh-vien","title":"Khám bệnh và mua thuốc","ko":"병원·약국 이용","icon":"🏥","group":"life","category":"life","description":"Đặt lịch, trình bày triệu chứng, hiểu toa thuốc","heading":"Kỹ năng sống: Khám bệnh và mua thuốc","short":"Đặt lịch, trình bày triệu chứng, hiểu toa thuốc","paragraphs":["Khi cần khám không khẩn cấp, hãy tìm cơ sở y tế phù hợp, kiểm tra giờ mở cửa và khả năng hỗ trợ ngôn ngữ. Với tình trạng nguy hiểm đến tính mạng, gọi 119.","Mang theo giấy tờ nhận dạng, thông tin bảo hiểm và danh sách thuốc đang dùng nếu có. Trình bày triệu chứng, thời điểm bắt đầu và tiền sử dị ứng một cách trung thực.","Không tự ý dùng thuốc không rõ tên hoặc uống theo toa của người khác. Nếu chưa hiểu liều lượng, hỏi dược sĩ hoặc nhân viên y tế.","Nếu cần phiên dịch, hãy hỏi cơ sở y tế về hỗ trợ ngôn ngữ. Trong tình huống cấp cứu, cung cấp tình trạng nguy hiểm trước rồi xác định người cần phiên dịch sau."],"facts":[],"tips":["Nếu có nguy hiểm trực tiếp tới tính mạng hoặc sức khỏe, gọi 119 hoặc 112 phù hợp với tình huống; 1330 chỉ hỗ trợ thông tin/phiên dịch du lịch."],"steps":[{"title":"Đánh giá mức độ khẩn","detail":"Trường hợp nguy hiểm gọi 119; các trường hợp khác tìm phòng khám/bệnh viện phù hợp."},{"title":"Chuẩn bị thông tin","detail":"Giấy tờ, bảo hiểm, các thuốc đang dùng, dị ứng."},{"title":"Mô tả triệu chứng","detail":"Triệu chứng gì, xuất hiện khi nào, diễn biến ra sao."},{"title":"Kiểm tra hướng dẫn","detail":"Đọc nhãn thuốc, hỏi lại liều dùng, tương tác và lịch tái khám."}],"words":[{"ko":"병원","vi":"Bệnh viện"},{"ko":"약국","vi":"Hiệu thuốc"},{"ko":"진료","vi":"Khám bệnh"},{"ko":"알레르기","vi":"Dị ứng"},{"ko":"처방전","vi":"Đơn thuốc"},{"ko":"아프다","vi":"Đau/ốm"}],"dialogue":[{"ko":"열이 나고 목이 아파요.","vi":"Tôi bị sốt và đau họng."},{"ko":"약을 어떻게 먹어야 해요?","vi":"Tôi nên uống thuốc thế nào?"}],"quizSet":[{"question":"Khi không hiểu cách dùng thuốc, bạn nên làm gì?","choices":["Tự tăng gấp đôi liều","Hỏi lại dược sĩ hoặc bác sĩ","Dùng thuốc của bạn cùng phòng"],"correct":1,"explanation":"Hãy dựa trên các bước xử lý an toàn đã hướng dẫn trong bài."}],"sourceLinks":[{"label":"Hỗ trợ y tế du khách – VISITKOREA","url":"https://english.visitkorea.or.kr/svc/contents/infoHtmlView.do?vcontsId=140042"}],"mediaLabel":"Hình minh họa kỹ năng thực tế · bản quyền MR LEE","image":"images/culture-v13/benh-vien.svg","realPhotos":[{"title":"Lối đến ga Bệnh viện Cảnh sát","explanation":"Ảnh cửa ra ga gần cơ sở y tế tại Seoul, không phải ảnh phòng khám. Kiểm tra đúng tên bệnh viện và vị trí trước khi đi.","filename":"Seoul subway national police hospital station exit 1.JPG","source":"https://commons.wikimedia.org/wiki/File:Seoul_subway_national_police_hospital_station_exit_1.JPG","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Seoul_subway_national_police_hospital_station_exit_1.JPG/540px-Seoul_subway_national_police_hospital_station_exit_1.JPG","local":"images/culture-v14/2a36a93c3bb5f7f7.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Khu cơ sở y tế – đào tạo tại Seoul","explanation":"Cụm cơ sở trường đại học và bệnh viện tại Seoul. Khi đi khám, cần chọn đúng tòa nhà/phòng ban, mang giấy tờ và thông tin bảo hiểm.","filename":"Seoul National University Yeongeon Campus at Naksan Park view.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul_National_University_Yeongeon_Campus_at_Naksan_Park_view.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Seoul_National_University_Yeongeon_Campus_at_Naksan_Park_view.jpg/540px-Seoul_National_University_Yeongeon_Campus_at_Naksan_Park_view.jpg","local":"images/culture-v14/91918470646b0af6.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Khi gặp sự cố an ninh trong hành trình","explanation":"Xe cảnh sát chỉ minh họa hỗ trợ an ninh. Với cấp cứu y tế nguy hiểm đến tính mạng hãy gọi 119; không nhầm với 112.","filename":"Police car in Seoul, South Korea.jpg","source":"https://commons.wikimedia.org/wiki/File:Police_car_in_Seoul,_South_Korea.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Police_car_in_Seoul,_South_Korea.jpg/540px-Police_car_in_Seoul,_South_Korea.jpg","local":"images/culture-v14/2ed3e5e0921f0d46.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"hoa-hoan","title":"Thoát hiểm khi cháy","ko":"화재 대피 요령","icon":"🧯","group":"life","category":"life","description":"Phát hiện cháy, báo 119, thoát ra an toàn","heading":"Kỹ năng sống: Thoát hiểm khi cháy","short":"Phát hiện cháy, báo 119, thoát ra an toàn","paragraphs":["Khi phát hiện khói hoặc cháy, báo động, gọi 119 từ nơi an toàn và tuân theo lối thoát hiểm được chỉ định tại tòa nhà.","Tránh dùng thang máy khi cháy. Nếu hành lang đầy khói hoặc lối thoát bị chặn, không lao qua vùng khói dày; liên hệ 119 và làm theo hướng dẫn tùy hoàn cảnh.","Không quay lại khu vực nguy hiểm để lấy hành lý. Nội quy thoát nạn riêng của tòa nhà luôn cần được xem trước.","Trong tòa nhà cao tầng, không tự mở cửa ra hành lang khi phía ngoài có dấu hiệu nhiệt độ cao hoặc khói đậm; làm theo hướng dẫn của 119 và sơ đồ thoát nạn tòa nhà."],"facts":[],"tips":["Nếu có nguy hiểm trực tiếp tới tính mạng hoặc sức khỏe, gọi 119 hoặc 112 phù hợp với tình huống; 1330 chỉ hỗ trợ thông tin/phiên dịch du lịch."],"steps":[{"title":"Cảnh báo","detail":"Báo mọi người, kích hoạt báo cháy nếu phù hợp và ở vị trí an toàn."},{"title":"Gọi 119","detail":"Nói rõ địa chỉ, tầng, vị trí lửa/khói và có người mắc kẹt hay không."},{"title":"Thoát theo lối an toàn","detail":"Dùng cầu thang bộ/lối thoát được chỉ dẫn; không đi thang máy."},{"title":"Không quay lại","detail":"Tới điểm tập kết, kiểm đếm và chờ chỉ dẫn."}],"words":[{"ko":"화재","vi":"Hỏa hoạn"},{"ko":"대피","vi":"Sơ tán"},{"ko":"비상구","vi":"Lối thoát hiểm"},{"ko":"연기","vi":"Khói"},{"ko":"소화기","vi":"Bình chữa cháy"},{"ko":"엘리베이터","vi":"Thang máy"}],"dialogue":[{"ko":"건물에 불이 났어요!","vi":"Tòa nhà bị cháy!"},{"ko":"비상구가 어디예요?","vi":"Lối thoát hiểm ở đâu?"}],"quizSet":[{"question":"Khi tòa nhà đang cháy, lựa chọn nào an toàn hơn?","choices":["Dùng thang máy","Theo biển thoát hiểm và tránh vùng khói nguy hiểm","Quay lại lấy ví"],"correct":1,"explanation":"Hãy dựa trên các bước xử lý an toàn đã hướng dẫn trong bài."}],"sourceLinks":[{"label":"Dịch vụ cứu hỏa 119 – VISITKOREA","url":"https://english.visitkorea.or.kr/svc/contents/infoHtmlView.do?vcontsId=140042"}],"mediaLabel":"Hình minh họa kỹ năng thực tế · bản quyền MR LEE","image":"images/culture-v13/hoa-hoan.svg","realPhotos":[{"title":"Xe cứu hỏa Hàn Quốc","explanation":"Xe chuyên dụng thực tế tại Seoul. Khi có cháy, kích hoạt báo động và gọi 119 từ khu vực an toàn, mô tả chính xác vị trí sự cố.","filename":"20170622 Hyundai Mighty fire engine of Seoul-side.jpg","source":"https://commons.wikimedia.org/wiki/File:20170622_Hyundai_Mighty_fire_engine_of_Seoul-side.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/20170622_Hyundai_Mighty_fire_engine_of_Seoul-side.jpg/540px-20170622_Hyundai_Mighty_fire_engine_of_Seoul-side.jpg","local":"images/culture-v14/23df912d2f90e751.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Hành lang công cộng và biển hướng dẫn","explanation":"Ảnh nhà ga không phải hiện trường cháy. Trong mọi tòa nhà, nên nhận diện sẵn cửa thoát hiểm, không chờ đến lúc có khói mới tìm đường.","filename":"Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg/540px-Seoul-metro-202-Euljiro-1ga-station-platform-20181122-075502.jpg","local":"images/culture-v14/2864ad555a023c67.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Phối hợp với cơ quan chức năng","explanation":"Trong sự cố lớn có thể có nhiều lực lượng hỗ trợ. Không tự quay lại khu vực cháy, làm theo cảnh sát và lực lượng cứu hỏa tại chỗ.","filename":"Police car in Seoul, South Korea.jpg","source":"https://commons.wikimedia.org/wiki/File:Police_car_in_Seoul,_South_Korea.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Police_car_in_Seoul,_South_Korea.jpg/540px-Police_car_in_Seoul,_South_Korea.jpg","local":"images/culture-v14/2ed3e5e0921f0d46.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"mat-dien-thoai","title":"Mất điện thoại & bảo mật","ko":"휴대전화 분실·보안","icon":"📱","group":"life","category":"life","description":"Khóa máy, SIM và tài khoản trong tình huống mất điện thoại","heading":"Kỹ năng sống: Mất điện thoại & bảo mật","short":"Khóa máy, SIM và tài khoản trong tình huống mất điện thoại","paragraphs":["Ưu tiên bảo vệ tài khoản hơn là tự mình truy tìm thiết bị tại nơi vắng vẻ. Nếu có thể, dùng tính năng tìm thiết bị từ máy khác và bật chế độ khóa/mất thiết bị.","Đổi mật khẩu quan trọng, đăng xuất phiên đăng nhập và liên hệ nhà mạng để khóa SIM nếu cần. Nếu nghi trộm cắp, báo cảnh sát 112; đồ thất lạc có thể kiểm tra LOST112.","Không chia sẻ mã OTP hoặc nhấp vào tin nhắn giả danh người nhặt máy yêu cầu nhập tài khoản.","Trước chuyến đi, bật tính năng xác thực hai bước và lưu mã khôi phục ở nơi an toàn. Không để toàn bộ giấy tờ/địa chỉ chỉ tồn tại trên một chiếc điện thoại."],"facts":[],"tips":["Nếu có nguy hiểm trực tiếp tới tính mạng hoặc sức khỏe, gọi 119 hoặc 112 phù hợp với tình huống; 1330 chỉ hỗ trợ thông tin/phiên dịch du lịch."],"steps":[{"title":"Bảo vệ truy cập","detail":"Từ thiết bị khác, khóa máy và đăng xuất tài khoản nhạy cảm."},{"title":"Bảo vệ số điện thoại","detail":"Liên hệ nhà mạng khóa SIM khi cần."},{"title":"Tra cứu đồ thất lạc","detail":"Liên hệ nơi vừa đến và LOST112; báo 112 nếu bị trộm."},{"title":"Cảnh giác lừa đảo","detail":"Không cung cấp OTP, mật khẩu hoặc thông tin ngân hàng cho người lạ."}],"words":[{"ko":"휴대전화","vi":"Điện thoại"},{"ko":"잠금","vi":"Khóa"},{"ko":"비밀번호","vi":"Mật khẩu"},{"ko":"통신사","vi":"Nhà mạng"},{"ko":"분실 신고","vi":"Báo mất"},{"ko":"인증번호","vi":"Mã xác thực"}],"dialogue":[{"ko":"휴대전화를 잃어버렸어요.","vi":"Tôi mất điện thoại."},{"ko":"유심을 정지하고 싶어요.","vi":"Tôi muốn khóa SIM."}],"quizSet":[{"question":"Sau khi mất điện thoại, điều gì không nên làm?","choices":["Khóa tài khoản","Đưa OTP cho người lạ","Liên hệ nhà mạng"],"correct":1,"explanation":"Hãy dựa trên các bước xử lý an toàn đã hướng dẫn trong bài."}],"sourceLinks":[{"label":"LOST112","url":"https://lost112.go.kr/"}],"mediaLabel":"Hình minh họa kỹ năng thực tế · bản quyền MR LEE","image":"images/culture-v13/mat-dien-thoai.svg","realPhotos":[{"title":"Kiểm tra ga tàu đã đi qua","explanation":"Khi nghi rơi điện thoại trên tàu, ghi tuyến, số ga và thời gian, nhờ nhân viên nhà ga hỗ trợ tìm đồ thất lạc.","filename":"Seoul-metro-531-Chungjeongno-station-platform-20180915-132214.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul-metro-531-Chungjeongno-station-platform-20180915-132214.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ec/Seoul-metro-531-Chungjeongno-station-platform-20180915-132214.jpg/540px-Seoul-metro-531-Chungjeongno-station-platform-20180915-132214.jpg","local":"images/culture-v14/ecd6e11e8e24a1fb.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Rơi thiết bị trên xe buýt","explanation":"Tìm số tuyến, hướng xe và thời gian lên/xuống. Đồng thời dùng thiết bị khác khóa điện thoại, SIM hoặc các tài khoản quan trọng.","filename":"Seoul Blue Bus.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul_Blue_Bus.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Seoul_Blue_Bus.jpg/540px-Seoul_Blue_Bus.jpg","local":"images/culture-v14/eb63e9656be01d60.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Báo cảnh sát nếu nghi bị trộm","explanation":"Ảnh minh họa lực lượng cảnh sát, không phải một vụ án. Không tự đến nơi nguy hiểm để truy tìm điện thoại.","filename":"Police car in Seoul, South Korea.jpg","source":"https://commons.wikimedia.org/wiki/File:Police_car_in_Seoul,_South_Korea.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Police_car_in_Seoul,_South_Korea.jpg/540px-Police_car_in_Seoul,_South_Korea.jpg","local":"images/culture-v14/2ed3e5e0921f0d46.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"}]},{"slug":"an-toan-giao-thong","title":"An toàn đi bộ & giao thông","ko":"보행·교통 안전","icon":"🚦","group":"life","category":"life","description":"Qua đường, gọi trợ giúp khi tai nạn, chú ý thời tiết","heading":"Kỹ năng sống: An toàn đi bộ & giao thông","short":"Qua đường, gọi trợ giúp khi tai nạn, chú ý thời tiết","paragraphs":["Ở Hàn Quốc, tuân thủ đèn tín hiệu, vạch qua đường và chú ý xe rẽ tại giao lộ. Không vừa đi vừa nhìn màn hình khi băng qua đường.","Nếu gặp tai nạn giao thông, đứng ở nơi an toàn, cảnh báo người khác; gọi 119 nếu có người bị thương và 112 nếu cần cảnh sát. Không tự ý di chuyển người bị thương nặng nếu không có nguy hiểm tức thì và không được hướng dẫn.","Mùa đông có thể có băng tuyết trên vỉa hè; cần giày phù hợp và đi chậm trên đoạn trơn trượt.","Tại khu vực có người đi xe đạp, xe máy giao hàng hoặc đường hẹp, giữ khoảng cách và không bất ngờ đổi hướng. Nếu tai nạn xảy ra, vị trí chính xác sẽ giúp đơn vị cứu hộ đến nhanh hơn."],"facts":[],"tips":["Nếu có nguy hiểm trực tiếp tới tính mạng hoặc sức khỏe, gọi 119 hoặc 112 phù hợp với tình huống; 1330 chỉ hỗ trợ thông tin/phiên dịch du lịch."],"steps":[{"title":"Chọn đường an toàn","detail":"Sử dụng vạch kẻ/đèn qua đường và chú ý phương tiện rẽ."},{"title":"Nếu xảy ra tai nạn","detail":"Rời khỏi nguồn nguy hiểm nếu có thể và cảnh báo người xung quanh."},{"title":"Gọi trợ giúp","detail":"119 cho người bị thương; 112 khi cần cảnh sát."},{"title":"Ghi nhận thông tin","detail":"Khi an toàn, ghi địa điểm và thông tin liên hệ; làm theo hướng dẫn cơ quan chức năng."}],"words":[{"ko":"횡단보도","vi":"Vạch qua đường"},{"ko":"신호등","vi":"Đèn tín hiệu"},{"ko":"교통사고","vi":"Tai nạn giao thông"},{"ko":"안전","vi":"An toàn"},{"ko":"미끄럽다","vi":"Trơn"},{"ko":"조심하세요","vi":"Cẩn thận"}],"dialogue":[{"ko":"여기서 길을 건너도 돼요?","vi":"Tôi qua đường ở đây được không?"},{"ko":"횡단보도를 이용하세요.","vi":"Hãy dùng vạch qua đường."}],"quizSet":[{"question":"Khi xảy ra tai nạn có người bị thương, cần gọi số nào để cấp cứu?","choices":["119","1330","114"],"correct":0,"explanation":"Hãy dựa trên các bước xử lý an toàn đã hướng dẫn trong bài."}],"sourceLinks":[{"label":"Dịch vụ khẩn cấp tại Hàn Quốc","url":"https://english.visitkorea.or.kr/svc/contents/infoHtmlView.do?vcontsId=140042"}],"mediaLabel":"Hình minh họa kỹ năng thực tế · bản quyền MR LEE","image":"images/culture-v13/an-toan-giao-thong.svg","realPhotos":[{"title":"Đèn tín hiệu đi bộ tại Seoul","explanation":"Ảnh đèn đỏ dành cho người đi bộ. Chỉ băng qua tại nơi cho phép và quan sát xe rẽ, kể cả khi tín hiệu cho người đi bộ bật xanh.","filename":"002 Pedestrian crossing embedded floor light - red light for pedestrians in Seoul, South Korea.jpg","source":"https://commons.wikimedia.org/wiki/File:002_Pedestrian_crossing_embedded_floor_light_-_red_light_for_pedestrians_in_Seoul,_South_Korea.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/002_Pedestrian_crossing_embedded_floor_light_-_red_light_for_pedestrians_in_Seoul,_South_Korea.jpg/540px-002_Pedestrian_crossing_embedded_floor_light_-_red_light_for_pedestrians_in_Seoul,_South_Korea.jpg","local":"images/culture-v14/8686c395a2fce541.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"Quan sát xe buýt ở điểm qua đường","explanation":"Xe buýt lớn có điểm mù khi rẽ. Không đi sát đầu hoặc đuôi xe, tránh vừa băng qua đường vừa nhìn điện thoại.","filename":"Seoul Blue Bus.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul_Blue_Bus.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Seoul_Blue_Bus.jpg/540px-Seoul_Blue_Bus.jpg","local":"images/culture-v14/eb63e9656be01d60.jpg","licenseNote":"Xem tác giả và giấy phép tại trang ảnh gốc Wikimedia Commons"},{"title":"An toàn tại điểm đón xe","explanation":"Đứng đúng khu vực chờ, không chạy xuống lòng đường khi xe còn di chuyển. Khi xuống xe, kiểm tra xe đạp và xe máy bên cạnh.","filename":"Seoul bus stop.jpg","source":"https://commons.wikimedia.org/wiki/File:Seoul_bus_stop.jpg","remote":"https://upload.wikimedia.org/wikipedia/commons/a/a7/Seoul_bus_stop.jpg","local":"images/culture-v14/a7cbe5f594887efb.jpg","licenseNote":"Ảnh: Trainholic; CC BY-SA 3.0 (https://creativecommons.org/licenses/by-sa/3.0/). Không chỉnh sửa ảnh."}]}];
